
              // Prevent standard circular reference crashes on JSON.stringify across the entire app
              window.currentLang = 'EN';
              window.toggleLanguage = function(e) {
                  e.preventDefault();
                  window.currentLang = window.currentLang === 'EN' ? 'BN' : 'EN';
                  document.querySelectorAll('.globalLangLabel').forEach(el => el.innerText = window.currentLang);
                  showToast("Language changed to " + window.currentLang, "info");
              };
              (function() {
                  
              window.getImg = function(item) {
                  if (item.image) return item.image;
                  if (item.img) return item.img;
                  const pid = item.productId || item.postId;
                  if (pid && typeof appPosts !== 'undefined') {
                      const p = appPosts.find(x => String(x.id) === String(pid));
                      if (p && p.images && p.images.length > 0) return p.images[item.imgIdx || 0] || p.images[0];
                  }
                  return 'https://picsum.photos/seed/placeholder/200/200';
              };

                  const originalStringify = JSON.stringify;
                  JSON.stringify = function(value, replacer, space) {
                      const seen = new WeakSet();
                      return originalStringify(value, function(key, val) {
                          if (val !== null && typeof val === 'object') {
                              if (seen.has(val)) {
                                  return "[Circular]";
                              }
                              seen.add(val);
                          }
                          
                          if ((key === 'image' || key === 'img' || key === 'productImageUrl') && typeof val === 'string' && val.length > 2000 && this && (this.productId || this.postId || this.cartId)) {
                              return ''; // Strip large images from orders/cart to prevent QuotaExceededError
                          }
                          if (replacer) {

                              return replacer(key, val);
                          }
                          return val;
                      }, space);
                  };

                  // Intercept and downgrade sandboxed Supabase connection warning logs to warnings
                  const originalConsoleLog = console.log;
                  const originalConsoleInfo = console.info;
                  
                  console.log = function(...args) {
                      const msg = args[0] ? String(args[0]) : '';
                      if (msg.includes('Supabase') || msg.includes('bexo_')) return;
                      originalConsoleLog.apply(console, args);
                  };
                  console.info = function(...args) {
                      const msg = args[0] ? String(args[0]) : '';
                      if (msg.includes('Supabase') || msg.includes('bexo_')) return;
                      originalConsoleInfo.apply(console, args);
                  };
                  const originalConsoleWarn = console.warn;
                  console.warn = function(...args) {
                      const msg = args[0] ? String(args[0]) : '';
                      if (msg.includes('Supabase') || msg.includes('bexo_')) {
                          return;
                      }
                      originalConsoleWarn.apply(console, args);
                  };
                  const originalConsoleError = console.error;
                  console.error = function(...args) {
                      const firstArg = args[0] ? String(args[0]) : '';
                      if (firstArg.includes('Could not reach Cloud Supabase backend') || firstArg.includes('Backend didn\'t respond within 10 seconds')) {
                           // Silenced to prevent console spam
                          return;
                      }
                       if (firstArg.includes('Supabase') || firstArg.includes('bexo_')) {
                           return;
                       }
                      originalConsoleError.apply(console, args);
                  };
              })();

