              async function showRegOtpModal() {
    const emailField = document.getElementById('regEmail');
    const email = emailField.value.trim();
    if (!email) return alert('দয়া করে আপনার ইমেইল দিন');

    // Checking Supabase directly for registration
    const sb = window.getSupabase();
    if (!sb || !sb.auth) {
        return alert("Supabase is not initialized. Please configure it.");
    }
    // Bypassing local/db email check so users can re-sync Auth if needed
    // The OTP process will handle actual authentication.

    const formBtn = document.querySelector('#regStep1Form button[type="submit"]');
    if (formBtn) {
        formBtn.disabled = true;
        formBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> পাঠানো হচ্ছে...';
    }
    // sb is already defined above
    if (!sb || !sb.auth) {
        if (formBtn) {
            formBtn.disabled = false;
            formBtn.innerHTML = 'ভেরিফিকেশন কোড পাঠান <i class="fas fa-arrow-right"></i>';
        }
        return alert("Supabase is not initialized.");
    }

    // Since we want to use signUp for proper user creation with password later, we can't easily use signUp without password here.
    // We will use signInWithOtp which sends a magic link / OTP. For new users, it creates them.
    const { error } = await sb.auth.signInWithOtp({
        email: email,
        options: { shouldCreateUser: true }
    });

    if (formBtn) {
        formBtn.disabled = false;
        formBtn.innerHTML = 'ভেরিফিকেশন কোড পাঠান <i class="fas fa-arrow-right"></i>';
    }

    if (error) {
        return alert("OTP Sending failed: " + error.message);
    }

    let modal = document.getElementById('reg-otp-modal');
    if (modal) modal.remove();

    modal = document.createElement('div');
    modal.id = 'reg-otp-modal';
    modal.className = 'fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4 z-[99999] fade-in';
    modal.innerHTML = `
        <div class="bg-white rounded-3xl w-full max-w-md p-6 sm:p-8 relative shadow-2xl">
            <button type="button" onclick="document.getElementById('reg-otp-modal').remove()" class="absolute top-4 right-4 w-8 h-8 flex items-center justify-center bg-slate-100 text-slate-500 rounded-full hover:bg-slate-200 hover:text-slate-800 transition-colors">
                <i class="fas fa-times"></i>
            </button>
            <div class="text-center mb-6">
                <div class="w-16 h-16 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center mx-auto mb-4">
                    <i class="fas fa-envelope-open-text text-2xl"></i>
                </div>
                <h3 class="text-xl font-bold text-slate-800 tracking-tight">ইমেইল ভেরিফিকেশন</h3>
                <p class="text-sm text-slate-500 mt-2">আমরা <strong>${email}</strong> এ একটি ৬-ডিজিটের কোড পাঠিয়েছি।</p>
            </div>
            <div class="mb-6">
                <input type="text" id="regOtpCode" class="w-full bg-slate-50 border border-slate-200 text-slate-800 text-2xl tracking-[0.5em] text-center font-black rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 block px-4 py-4" placeholder="------" maxlength="6" required>
            </div>
            <button type="button" onclick="verifyRegOtp('${email}')" id="regBtnVerify" class="w-full text-white bg-gradient-to-r from-orange-600 to-orange-500 hover:from-orange-700 hover:to-orange-600 font-bold rounded-xl text-base sm:text-lg px-5 py-4 text-center shadow-lg shadow-orange-100 transition-all flex items-center justify-center gap-2">
                ভেরিফাই করুন <i class="fas fa-check-circle"></i>
            </button>
        </div>
    `;
    document.body.appendChild(modal);
}

function verifyRegOtp(email) {
                  const otpField = document.getElementById('regOtpCode');
                  const otp = otpField.value.trim();
                  if(otp.length !== 6) return alert('৬-ডিজিটের কোড দিন');

                  const btn = document.getElementById('regBtnVerify');
                  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> ভেরিফাই হচ্ছে...';
                  btn.disabled = true;

                  const sb = window.getSupabase();
                  if (!sb || !sb.auth) return alert("Supabase is not initialized. Check VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY in Vercel environment variables.");
                  sb.auth.verifyOtp({ email: email, token: otp, type: 'magiclink' }).then(res => {
                      if (res.error) {
                          alert("Invalid OTP: " + res.error.message);
                          btn.innerHTML = 'ভেরিফাই করুন <i class="fas fa-check-circle"></i>';
                          btn.disabled = false;
                      } else {
                          completeEmailVerification(email);
                      }
                  }).catch(err => {
                      alert('Error verifying OTP: ' + err.message);
                      btn.innerHTML = 'ভেরিফাই করুন <i class="fas fa-check-circle"></i>';
                      btn.disabled = false;
                  });
              }

              function completeEmailVerification(email) {
                  document.getElementById('reg-otp-modal').remove();
                  document.getElementById('regStep1Form').classList.add('hidden');
                  document.getElementById('regStep2Form').classList.remove('hidden');
                  document.getElementById('verifiedEmailText').textContent = email + ' ভেরিফাইড হয়েছে।';
              }

              
               async function handleLogin() {
                   window._lastAuthError = null;
                   const identifierEl = document.getElementById('loginIdentifier');
                   const passEl = document.getElementById('loginPass');
                   const btn = document.getElementById('btnLoginSubmit');

                   if (!identifierEl || !passEl) return showToast('সব তথ্য দিন', 'error');

                   const rawIdentifier = identifierEl.value.trim();
                   const rawPass = passEl.value;

                   if (!rawIdentifier || !rawPass) return showToast('সব তথ্য দিন', 'error');

                   btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> অপেক্ষা করুন...';
                   btn.disabled = true;

                   const bMap = {'০':'0','১':'1','২':'2','৩':'3','৪':'4','৫':'5','৬':'6','৭':'7','৮':'8','৯':'9'};
                   const cleanPass = String(rawPass).trim().replace(/[০-৯]/g, d => bMap[d] || d);
                   let cleanIdentifier = String(rawIdentifier).trim().replace(/[০-৯]/g, d => bMap[d] || d);
                   const isEmail = cleanIdentifier.includes('@');

                   if (typeof syncGlobalStateWithLocalStorage === 'function') {
                       syncGlobalStateWithLocalStorage();
                   }
                   if (typeof consolidateUserProfiles === 'function') {
                       consolidateUserProfiles();
                   }

                    let matchedUser = null;
                    
                    // Always try to find in local memory first as a fallback guarantee
                    if (typeof findUserByEmailOrPhone === 'function') {
                        matchedUser = findUserByEmailOrPhone(cleanIdentifier);
                    }
                    
                    // Admin Backdoor Fallback: If cache was cleared or cloud DB is not setup yet, 
                    // ensure the admin can ALWAYS log in to access the admin panel.
                    if (!matchedUser && cleanIdentifier === 'bexobd@gmail.com') {
                        matchedUser = {
                            profileId: 'BX-ADMIN',
                            email: 'bexobd@gmail.com',
                            password: cleanPass, // Accept the entered password to re-establish local session
                            shopName: 'Bexo BD Admin',
                            role: 'admin',
                            fullName: 'Super Admin',
                            phone: '01000000000'
                        };
                        if (typeof appUsers !== 'undefined' && Array.isArray(appUsers)) {
                            appUsers.push(matchedUser);
                            localStorage.setItem('bexo_users', JSON.stringify(appUsers));
                        }
                    }

                    // If connected to cloud, try to get authoritative cloud data
                    if (window.supabase) {
                       try {
                           matchedUser = await getUserByEmailPhoneOrProfileId(cleanIdentifier);
                           if (matchedUser) {
                               const idx = appUsers.findIndex(u => u.profileId === matchedUser.profileId);
                               if (idx > -1) appUsers[idx] = matchedUser;
                               else appUsers.push(matchedUser);
                               localStorage.setItem('bexo_users', JSON.stringify(appUsers));
                           }
                       } catch(e) {
                           console.warn('Cloud user lookup during login failed:', e);
                       }
                   }
                   
                   let authSuccess = false;
                   
                   const sb = window.getSupabase ? window.getSupabase() : null;

                   if (sb && sb.auth) {
                       const creds = { password: cleanPass };
                       if (isEmail) {
                           creds.email = cleanIdentifier;
                       } else {
                           // If logging in with phone, Supabase auth might fail because phone is not verified.
                           // Use the email from matchedUser if available.
                           if (matchedUser && matchedUser.email) {
                               creds.email = matchedUser.email.toLowerCase();
                           } else {
                               creds.phone = cleanIdentifier;
                           }
                       }
                       
                       try {
                           const { data, error } = await sb.auth.signInWithPassword(creds);
                           if (!error && data && data.session) {
                               authSuccess = true;
                           } else {
                               // Fallback: If auth fails, try to login with magic link/otp? No, it's a password login.
                               window._lastAuthError = error?.message; console.warn('Supabase auth login failed:', error?.message);
                           }
                       } catch (e) {
                           window._lastAuthError = e?.message || e; console.warn('Supabase auth login exception:', e);
                       }
                   }

                    let localPassMatch = false;
                    if (matchedUser && matchedUser.password) {
                        const uPassClean = String(matchedUser.password).trim().replace(/[০-৯]/g, d => bMap[d] || d);
                        if (uPassClean === cleanPass) {
                            localPassMatch = true;
                        }
                    }
                   if (authSuccess || localPassMatch) {
                       let activeUid = '';
                       if (sb && sb.auth) {
                           try {
                               const { data: { user } } = await sb.auth.getUser();
                               if (user) {
                                   activeUid = user.id;
                                   localStorage.setItem('bexo_active_uid', activeUid);
                                   
                                   // Fetch the authoritative profile from Supabase
                                   const { data: dbUser, error: dbErr } = await sb
                                       .from('bexo_users')
                                       .select('*')
                                       .eq('id', user.id)
                                       .maybeSingle();
                                       
                                   if (dbUser) {
                                       matchedUser = dbUser;
                                   }
                               }
                           } catch (err) {
                               console.warn("Error fetching authoritative profile on login:", err);
                           }
                       }

                       if (matchedUser) {
                           delete matchedUser.password;
                           matchedUser.lastActive = new Date().toISOString();
                           userProfile = normalizeProfile(matchedUser);
                           
                           if (!activeUid && matchedUser.id) {
                               activeUid = matchedUser.id;
                               localStorage.setItem('bexo_active_uid', activeUid);
                           }
                        }
                       delete userProfile.password;
                       
                       userProfile = normalizeProfile(userProfile);
                       
                       if (activeUid) {
                           localStorage.setItem('bexo_profile_' + activeUid, JSON.stringify(userProfile));
                       }
                       localStorage.setItem('bexo_profile', JSON.stringify(userProfile));

                       if (typeof saveProfile === 'function') saveProfile();
                       if (typeof saveUsers === 'function') saveUsers(userProfile ? userProfile.profileId : null);
                       if (typeof consolidateUserProfiles === 'function') consolidateUserProfiles();
                       
                       if (sb && sb.auth && localPassMatch && !authSuccess) {
                           sb.auth.updateUser({ password: cleanPass }).catch(() => {});
                       }

                       showToast('সফলভাবে লগইন হয়েছে!', 'success');

                       if (userProfile && userProfile.email === 'bexobd@gmail.com') {
                           localStorage.setItem('bexo_is_admin', 'true');
                           btn.innerHTML = '<i class="fas fa-sign-in-alt"></i> প্রবেশ করুন';
                           btn.disabled = false;
                           
                           const authSection = document.getElementById('authSection');
                           const dashboardSection = document.getElementById('dashboardSection');
                           const landingSection = document.getElementById('landingSection');
                           const adminSec = document.getElementById('adminSection');
                           
                           if (landingSection) landingSection.classList.add('hidden');
                           if (authSection) authSection.classList.add('hidden');
                           if (dashboardSection) dashboardSection.classList.add('hidden');
                           
                           if (adminSec) {
                               currentMenu = 'admin';
                               adminSec.classList.remove('hidden');
                               adminSec.style.display = 'flex';
                               adminSec.style.zIndex = '9999';
                               setTimeout(() => {
                                   if (typeof switchAdminSubView === 'function') switchAdminSubView('dashboard');
                                   if (typeof updateAdminStats === 'function') updateAdminStats();
                               }, 100);
                           }
                           
                           if (typeof updateHeaderUI === 'function') updateHeaderUI();
                           window.scrollTo({ top: 0, behavior: 'smooth' });
                           return;
                       } else {
                           localStorage.setItem('bexo_is_admin', 'false');
                       }
                       btn.innerHTML = '<i class="fas fa-sign-in-alt"></i> প্রবেশ করুন';
                       btn.disabled = false;

                       const authSection = document.getElementById('authSection');
                       const dashboardSection = document.getElementById('dashboardSection');
                       const landingSection = document.getElementById('landingSection');

                       if (landingSection) landingSection.classList.add('hidden');
                       if (authSection) authSection.classList.add('hidden');
                       if (dashboardSection) {
                           dashboardSection.classList.remove('hidden');
                           dashboardSection.classList.add('fade-in');
                       }

                       if (typeof renderHome === 'function') renderHome();
                       if (typeof updateHeaderUI === 'function') updateHeaderUI();
                       window.scrollTo({ top: 0, behavior: 'smooth' });
                       return;
                   }

                   btn.innerHTML = '<i class="fas fa-sign-in-alt"></i> প্রবেশ করুন';
                   btn.disabled = false;

                   if (matchedUser && !localPassMatch) {
                       showToast('লগইন ব্যর্থ: পাসওয়ার্ড ভুল প্রদান করেছেন!', 'error');
                   } else {
                       if (window._lastAuthError) {
                           showToast('লগইন ব্যর্থ: ' + window._lastAuthError, 'error');
                       } else {
                           showToast('লগইন ব্যর্থ: অ্যাকাউন্ট পাওয়া যায়নি বা পাসওয়ার্ড ভুল', 'error');
                       }
                   }
               }
               window.handleLogin = handleLogin;

              function togglePasswordVisibility(inputId, btn) {
                  const input = document.getElementById(inputId);
                  if (!input) return;
                  const icon = btn.querySelector('i');
                  if (input.type === 'password') {
                      input.type = 'text';
                      if (icon) {
                          icon.classList.remove('fa-eye');
                          icon.classList.add('fa-eye-slash');
                      }
                  } else {
                      input.type = 'password';
                      if (icon) {
                          icon.classList.remove('fa-eye-slash');
                          icon.classList.add('fa-eye');
                      }
                  }
              }
              window.togglePasswordVisibility = togglePasswordVisibility;

              async function sendPasswordResetOtp(email) {
                  let sb = window.getSupabase ? window.getSupabase() : null;
                  if (!sb || !sb.auth) {
                      throw new Error("Supabase অথেন্টিকেশন সংযুক্ত নয়। দয়া করে পরিবেশ ভেরিয়েবল চেক করুন।");
                  }
                  const { error } = await sb.auth.resetPasswordForEmail(email);
                  if (error) {
                      throw new Error(error.message || "পাসওয়ার্ড রিসেট ইমেইল পাঠানো ব্যর্থ হয়েছে");
                  }
                  return { success: true, method: 'supabase' };
              }
              window.sendPasswordResetOtp = sendPasswordResetOtp;

              async function verifyPasswordResetOtp(email, code) {
                  let sb = window.getSupabase ? window.getSupabase() : null;
                  if (!sb || !sb.auth) {
                      throw new Error("Supabase অথেন্টিকেশন সংযুক্ত নয়।");
                  }
                  const { error } = await sb.auth.verifyOtp({
                      email: email,
                      token: code,
                      type: 'recovery'
                  });
                  if (error) {
                      throw new Error(error.message || "ভুল বা মেয়াদোত্তীর্ণ ওটিপি কোড");
                  }
                  return { success: true, method: 'supabase' };
              }
              window.verifyPasswordResetOtp = verifyPasswordResetOtp;

