                            async function handleGoogleAuth() {
                  try {
                      if (!window.supabase) {
                          showToast("Supabase লোড হচ্ছে, অনুগ্রহ করে একটু অপেক্ষা করুন...", "info");
                          return;
                      }
                      
                      const triggerAuthProcess = async (loggedInUser) => {
                          console.log("Google Sign-In success:", loggedInUser.email);
                          
                          // Check if user has an existing account in our database
                          let foundUser = null;
                           if (!window.supabase && Array.isArray(appUsers)) {
                              foundUser = appUsers.find(u => u.email && u.email.toLowerCase().trim() === loggedInUser.email.toLowerCase().trim());
                          }
                          
                          if (!foundUser) {
                               if (window.supabase) {
                                   try {
                                       foundUser = await getUserByEmailPhoneOrProfileId(loggedInUser.email);
                                   } catch(e) {
                                       console.warn("Supabase check failed:", e);
                                   }
                               }
                           }
                          
                          if (!foundUser) {
                              // Sign up: Create a new profile
                              const isSuperAdminEmail = loggedInUser.email === 'bexobd@gmail.com';
                              
                              // Generate unique seller code for Passive Income
                              let sCode = '';
                              while (true) {
                                  sCode = 'BX' + Math.floor(100 + Math.random() * 900);
                                  if (Array.isArray(appUsers)) {
                                      if (!appUsers.some(u => u.sellerCode === sCode)) break;
                                  } else {
                                      break;
                                  }
                              }
                              
                              foundUser = {
                                  ...DEFAULT_PROFILE,
                                  profileId: 'BX-' + Math.floor(100000 + Math.random() * 900000),
                                  fullName: loggedInUser.user_metadata?.full_name || loggedInUser.email.split('@')[0],
                                  email: loggedInUser.email,
                                  password: 'google_' + loggedInUser.id,
                                  sellerCode: sCode,
                                  role: isSuperAdminEmail ? 'admin' : 'user',
                                  joinDate: new Date().toLocaleDateString('bn-BD'),
                                  createdAt: Date.now()
                              };
                              
                              updateAppUsersList(foundUser);
                              showToast("Google অ্যাকাউন্ট সফলভাবে রেজিস্টার করা হয়েছে!", "success");
                          } else {
                              showToast("Google অ্যাকাউন্ট সফলভাবে লগইন করা হয়েছে!", "success");
                          }
                          userProfile = { ...DEFAULT_PROFILE, ...foundUser };
                          userProfile.lastActive = new Date().toISOString();
                          if (Array.isArray(appUsers)) {
                              const uIdx = appUsers.findIndex(u => String(u.profileId) === String(userProfile.profileId));
                              if (uIdx > -1) {
                                  appUsers[uIdx].lastActive = userProfile.lastActive;
                                  saveUsers(userProfile.profileId);
                              }
                          }
                          saveProfile();
                          
                          if (userProfile.role === 'admin') {
                              localStorage.setItem('bexo_is_admin', 'true');
                          }
                          
                          const auth = document.getElementById('authSection');
                          const dash = document.getElementById('dashboardSection');
                          const admin = document.getElementById('adminSection');
                          const landing = document.getElementById('landingPage');
                          
                          if (auth) auth.classList.add('hidden');
                          if (landing) landing.classList.add('hidden');
                          
                          if (userProfile.role === 'admin') {
                              if (admin) admin.classList.remove('hidden');
                              if (typeof renderAdminDashboard === 'function') renderAdminDashboard();
                              const adminSub = localStorage.getItem('bexo_admin_subview') || 'dashboard';
                              switchAdminView(adminSub);
                          } else {
                              if (dash) dash.classList.remove('hidden');
                              if (typeof renderHome === 'function') renderHome();
                          }
                          
                          updateHeaderUI();
                      };
                      
                      showToast("Google সাইন-ইন উইন্ডো খোলা হচ্ছে...", "info");
                      try {
                          const sb = window.getSupabase();
                          if (!sb || !sb.auth) return showToast("Supabase is not initialized.", "error");
                          const { data, error } = await sb.auth.signInWithOAuth({
                              provider: 'google',
                              options: {
                                  queryParams: {
                                      access_type: 'offline',
                                      prompt: 'consent',
                                  },
                                  skipBrowserRedirect: true // Uses popup if possible, else redirects
                              }
                          });
                          if (error) throw error;
                          
                          // On successful sign-in, if skipBrowserRedirect is false, the page will reload.
                          // If skipBrowserRedirect is true, we might need to handle the session manually.
                          // Let's use the standard redirect for now, which is more reliable in AI Studio.
                          
                          if (sb && sb.auth) sb.auth.signInWithOAuth({
                              provider: 'google',
                              options: {
                                  redirectTo: window.location.origin
                              }
                          });
                      } catch (err) {
                          console.warn("Google OAuth failed, using fallback assistant:", err);
                          showGoogleFallbackModal(async (mockUser) => {
                              await triggerAuthProcess({
                                  id: mockUser.uid,
                                  email: mockUser.email || document.getElementById('fallback-google-email-input').value,
                                  user_metadata: { full_name: 'Mock User' }
                              });
                          });
                      }
                      
                  } catch (err) {
                      console.error("Google Auth failed inside index.html:", err);
                      showToast("Google অথেনটিকেশন ব্যর্থ হয়েছে: " + err.message, "error");
                  }
              }

                  const sb = window.getSupabase ? window.getSupabase() : null;
              function logout() {
                  // Sign out of Supabase Auth session if active
                  
                  if (sb && sb.auth) {
                      sb.auth.signOut().catch(err => console.warn("Supabase signOut error:", err));
                  }
                  
                  // Clear active sessions
                  localStorage.removeItem('bexo_profile');
                  localStorage.removeItem('bexo_is_admin');
                  localStorage.removeItem('bexo_active_uid');
                  userProfile = { ...DEFAULT_PROFILE };
                  
                  const auth = document.getElementById('authSection');
                  const dash = document.getElementById('dashboardSection');
                  const admin = document.getElementById('adminSection');
                  var landing = document.getElementById('landingSection');

                  if (landing) {
                      landing.classList.remove('hidden');
                      auth.classList.add('hidden');
                  } else {
                      auth.classList.remove('hidden');
                  }
                  
                  dash.classList.add('hidden');
                  admin.classList.add('hidden');

                  // Explicitly show login form, hide registration
                  toggleAuth(true);

                  // Clear input fields
                  if(document.getElementById('loginPhone')) document.getElementById('loginPhone').value = '';
                  if(document.getElementById('loginPass')) document.getElementById('loginPass').value = '';
                  const logoutAlert = document.getElementById('loginAlert');
                  if(logoutAlert) logoutAlert.classList.add('hidden');
                  
                  showToast("সফলভাবে লগআউট করা হয়েছে।", "info");
              }

              function updateHeaderUI() {
                  if (!userProfile || !userProfile.profileId) return;

                  // Ensure arrays exist
                  if (!userProfile.cart) userProfile.cart = [];
                  if (!userProfile.orders) userProfile.orders = [];
                  if (!userProfile.favorites) userProfile.favorites = [];
                  if (userProfile.deliveredOrdersCount === undefined) userProfile.deliveredOrdersCount = 0;

                  // Update profile button image if avatar is set
                  const userProfileBtn = document.getElementById('userProfileBtn');
                  if (userProfileBtn) {
                      if (userProfile.avatar) {
                          userProfileBtn.innerHTML = `
                              <img src="${userProfile.avatar}" class="w-full h-full object-cover rounded-full">
                              <div id="userVerifyBadge"></div>
                          `;
                      } else {
                          userProfileBtn.innerHTML = `
                              <i class="fas fa-user-ninja text-white text-lg"></i>
                              <div id="userVerifyBadge"></div>
                          `;
                      }
                  }

                  // Update Main Badge on Button
                  const verifyBadge = document.getElementById('userVerifyBadge');
                  if (verifyBadge) {
                      if (userProfile.deliveredOrdersCount >= 10) {
                          verifyBadge.innerHTML = `
                              <div class="absolute -top-1 -right-1 bg-emerald-500 text-white w-4 h-4 rounded-full flex items-center justify-center border-2 border-orange-600 shadow-sm">
                                  <i class="fas fa-check text-[6px]"></i>
                              </div>
                          `;
                      } else {
                          verifyBadge.innerHTML = '';
                      }
                  }

                  // Update Dropdown Content
                  const dropdownBadges = document.getElementById('dropdownBadges');
                  if (dropdownBadges) {
                      let badgesHtml = '';
                      if (userProfile.deliveredOrdersCount >= 10) badgesHtml += '<i class="fas fa-check-circle text-emerald-500 text-[10px]" title="Verified Seller"></i>';
                      if (userProfile.hasPremiumCourse) badgesHtml += '<i class="fas fa-play-circle text-amber-500 text-[10px]" title="Premium Video Access"></i>';
                      if (userProfile.hasWebsite) badgesHtml += '<i class="fas fa-globe text-blue-500 text-[10px]" title="Website Owner"></i>';
                      dropdownBadges.innerHTML = badgesHtml;
                  }

                  const dropdownName = document.getElementById('dropdownUserName');
                  if (dropdownName) dropdownName.innerText = userProfile.fullName || 'User Name';

                  const dropdownId = document.getElementById('dropdownProfileId');
                  if (dropdownId) dropdownId.innerText = userProfile.profileId;

                  if (typeof updateNotificationIconBadge === 'function') {
                      updateNotificationIconBadge();
                  }
              }

              function toggleUserDropdown(event) {
                  event.stopPropagation();
                  updateHeaderUI();
                  const dropdown = document.getElementById('userDropdown');
                  dropdown.classList.toggle('hidden');
              }

              let isBalanceVisible = false;
              function toggleBalanceVisibility() {
                  const balanceValue = document.getElementById('balanceValue');
                  const balanceEye = document.getElementById('balanceEye');
                  const lastBalance = userProfile.rechargeBalance || 0;

                  // Sync with current balance before showing
                  document.getElementById('headerBalanceAmount').innerText = lastBalance.toLocaleString(undefined, {minimumFractionDigits: 2});

                  isBalanceVisible = !isBalanceVisible;

                  if (isBalanceVisible) {
                      balanceValue.classList.remove('blur-[5px]');
                      balanceEye.innerHTML = '<i class="fas fa-eye-slash text-[10px]"></i>';
                      balanceEye.classList.add('bg-orange-100');
                  } else {
                      balanceValue.classList.add('blur-[5px]');
                      balanceEye.innerHTML = '<i class="fas fa-eye text-[10px]"></i>';
                      balanceEye.classList.remove('bg-orange-100');
                  }
              }

              function closeUserDropdown() {
                  const dropdown = document.getElementById('userDropdown');
                  if (dropdown) dropdown.classList.add('hidden');
              }

              // Close dropdown when clicking outside
              window.addEventListener('click', () => {
                  closeUserDropdown();
                  closeNotificationDropdown();
              });

              function toggleNotificationDropdown(event) {
                  event.stopPropagation();
                  closeUserDropdown(); // Close user dropdown when notification dropdown is opened
                  const dropdown = document.getElementById('notificationDropdown');
                  if (dropdown) {
                      dropdown.classList.toggle('hidden');
                      if (!dropdown.classList.contains('hidden')) {
                          renderNotifications();
                      }
                  }
              }

              function closeNotificationDropdown() {
                  const dropdown = document.getElementById('notificationDropdown');
                  if (dropdown) dropdown.classList.add('hidden');
              }

              function updateNotificationIconBadge() {
                  const badge = document.getElementById('notificationUnreadBadge');
                  if (!badge) return;

                  const notifs = (userProfile && userProfile.notifications) ? userProfile.notifications : [];
                  const unreadCount = notifs.filter(n => !n.read).length;

                  if (unreadCount > 0) {
                      badge.innerText = unreadCount;
                      badge.classList.remove('hidden');
                  } else {
                      badge.classList.add('hidden');
                  }
              }

              function renderNotifications() {
                  const container = document.getElementById('notificationListContainer');
                  if (!container) return;

                  const notifs = (userProfile && userProfile.notifications) ? userProfile.notifications : [];
                  if (notifs.length === 0) {
                      container.innerHTML = `
                          <div class="p-4 sm:p-8 text-center text-slate-400">
                              <div class="w-12 h-12 bg-slate-50 text-slate-300 rounded-full flex items-center justify-center mx-auto mb-3">
                                  <i class="fas fa-bell text-xl"></i>
                              </div>
                              <p class="text-[12px] font-bold leading-tight">কোনো নোটিফিকেশন নেই</p>
                          </div>
                      `;
                      return;
                  }

                  container.innerHTML = notifs.map(notif => {
                      const isUnread = !notif.read;
                      const bgClass = isUnread ? 'bg-orange-50/70 border-l-4 border-orange-500' : 'hover:bg-slate-50 border-l border-transparent';
                      const dotClass = isUnread ? 'bg-orange-500' : 'bg-transparent';
                      
                      let clickAction = '';
                      if (notif.type === 'profile_update') {
                          clickAction = `onclick="handleNotificationClick('${notif.id}', 'profile')"`;
                      } else {
                          clickAction = `onclick="handleNotificationClick('${notif.id}')"`;
                      }

                      return `
                          <div ${clickAction} class="p-4 flex gap-3 transition-all cursor-pointer ${bgClass}">
                              <div class="w-9 h-9 bg-orange-100/50 text-orange-600 rounded-xl flex items-center justify-center shrink-0">
                                  <i class="fas ${notif.type === 'profile_update' ? 'fa-user-edit' : 'fa-bell'} text-sm"></i>
                              </div>
                              <div class="flex-1 min-w-0">
                                  <div class="flex items-start justify-between gap-1">
                                      <h4 class="text-[12px] font-black text-slate-800 leading-tight truncate">${notif.title}</h4>
                                      <span class="w-2 h-2 rounded-full ${dotClass} shrink-0 mt-1"></span>
                                  </div>
                                  <p class="text-[11px] text-slate-600 font-bold mt-1 leading-snug">${notif.message}</p>
                                  <div class="flex items-center justify-between gap-1 mt-2">
                                      <p class="text-[9px] text-slate-400 font-bold font-mono">${notif.date}</p>
                                      ${isUnread ? `<span class="text-[9px] font-black text-orange-600">নতুন</span>` : ''}
                                  </div>
                              </div>
                          </div>
                      `;
                  }).join('');
              }

              function handleNotificationClick(notifId, actionMenu = null) {
                  const notifs = (userProfile && userProfile.notifications) ? userProfile.notifications : [];
                  const notif = notifs.find(n => n.id === notifId);
                  if (notif) {
                      notif.read = true;
                      saveProfile();
                      updateNotificationIconBadge();
                  }
                  
                  if (actionMenu) {
                      switchMenu(actionMenu);
                  }
                  
                  closeNotificationDropdown();
                  
                  if (typeof renderHome === 'function') {
                      renderHome();
                  }
              }

              function readAllNotifications() {
                  const notifs = (userProfile && userProfile.notifications) ? userProfile.notifications : [];
                  if (notifs.length === 0) return;
                  notifs.forEach(n => n.read = true);
                  saveProfile();
                  updateNotificationIconBadge();
                  renderNotifications();
                  showToast("সব নোটিফিকেশন পঠিত হিসেবে চিহ্নিত করা হয়েছে।", "success");
                  
                  if (typeof renderHome === 'function') {
                      renderHome();
                  }
              }

              function dismissWarningNotification() {
                  if (userProfile && userProfile.notifications) {
                      userProfile.notifications.forEach(n => {
                          if (n.type === 'profile_update') {
                              n.read = true;
                          }
                      });
                      saveProfile();
                      updateNotificationIconBadge();
                      
                      const banner = document.getElementById('unreadNotificationBanner');
                      if (banner) {
                          banner.classList.add('hidden');
                      }
                  }
              }

              function sendProfileUpdateNotification(profileId) {
                  if (!profileId) {
                      showToast("রিসেলার আইডি পাওয়া যায়নি", "error");
                      return;
                  }
                  const idx = appUsers.findIndex(u => u.profileId === profileId);
                  if (idx === -1) {
                      showToast("রিসেলার খুঁজে পাওয়া যায়নি", "error");
                      return;
                  }
                  const targetUser = appUsers[idx];
                  targetUser.notifications = targetUser.notifications || [];
                  
                  const hasUnread = targetUser.notifications.some(n => n.type === 'profile_update' && !n.read);
                  if (hasUnread) {
                      showToast("ইতিমধ্যে একটি নোটিফিকেশন পাঠানো আছে এবং অপঠিত রয়েছে।", "info");
                      return;
                  }

                  const notif = {
                      id: 'notif_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
                      type: 'profile_update',
                      title: 'প্রোফাইল আপডেট করুন',
                      message: 'আপনার শপের নাম এবং গুরুত্বপূর্ণ তথ্য আপডেট করা নেই। দয়া করে প্রোফাইল সেটিংসে যেয়ে দ্রুত আপনার শপের নাম সেট করুন।',
                      date: new Date().toLocaleString('bn-BD'),
                      read: false
                  };

                  targetUser.notifications.unshift(notif);
                  saveUsers(profileId);

                  if (userProfile && userProfile.profileId === profileId) {
                      userProfile.notifications = userProfile.notifications || [];
                      userProfile.notifications.unshift(notif);
                      saveProfile();
                      updateNotificationIconBadge();
                  }

                  showToast("নোটিফিকেশন পাঠানো হয়েছে!", "success");
              }

