              function updateAdminStats() {
                  try {
                      syncGlobalStateWithLocalStorage();
                      const sidebarUsers = document.getElementById('adminSidebarUserCount');
                      // Real Live Users (Active in last 5 minutes)
                      const liveCount = (appUsers || []).filter(u => {
                          if(!u.lastActive || u.lastActive === 'Never') return false;
                          const lastActiveDate = new Date(u.lastActive);
                          const now = new Date();
                          return (now - lastActiveDate) < 5 * 60 * 1000;
                      }).length;
                      if(sidebarUsers) sidebarUsers.innerText = liveCount;

                      const hasDash = document.getElementById('adminDashboardTimeFilterSelect');
                      if (hasDash) {
                          renderAdminDashboard();
                      } else {
                          const userCount = (appUsers || []).length;
                          const dashUsers = document.getElementById('dashTotalUsers');
                          if(dashUsers) dashUsers.innerText = userCount;

                          const dashOrders = document.getElementById('dashPendingOrders');
                          if(dashOrders) dashOrders.innerText = (appOrders || []).filter(o => o.status === 'Pending').length;

                          const dashSales = document.getElementById('dashTotalSales');
                          if(dashSales) {
                              const total = (appOrders || []).reduce((acc, curr) => acc + (Number(curr.grandTotal) || 0), 0);
                              dashSales.innerText = '৳ ' + total.toLocaleString();
                          }

                          const dashProfit = document.getElementById('dashTotalProfit');
                          if(dashProfit) {
                              const profit = (appOrders || []).reduce((acc, curr) => acc + (Number(curr.totalProfit) || 0), 0);
                              dashProfit.innerText = '৳ ' + profit.toLocaleString();
                          }
                      }

                      // Daily Sales
                      const dSales = document.getElementById('adminDailySales');
                      if (dSales) {
                          const today = new Date().toDateString();
                          const daily = (appOrders || []).filter(o => {
                              const dateString = o.date ? (o.date.includes(',') ? o.date.split(',')[0] : o.date) : '';
                              const date = dateString ? new Date(dateString).toDateString() : '';
                              return date === today && (o.status === 'Completed' || o.status === 'Delivered' || o.status === 'Delivery Completed');
                          }).reduce((sum, o) => sum + (Number(o.grandTotal) || 0), 0);
                          dSales.innerText = daily.toLocaleString();
                      }
                  } catch (e) {
                      console.error("Stats update failed:", e);
                  }
              }

