               async function getSafeBlob(url) {
                   if (url.startsWith('data:')) {
                       try {
                           const parts = url.split(',');
                           const mimeString = parts[0].split(':')[1].split(';')[0];
                           const byteString = atob(parts[1]);
                           const ab = new ArrayBuffer(byteString.length);
                           const ia = new Uint8Array(ab);
                           for (let i = 0; i < byteString.length; i++) {
                               ia[i] = byteString.charCodeAt(i);
                           }
                           return new Blob([ab], { type: mimeString });
                       } catch (e) {
                           console.error("Base64 decoding failed:", e);
                           throw e;
                       }
                   } else {
                       // Try direct fetch first (takes advantage of browser cache/cors)
                       try {
                           const res = await fetch(url, { mode: 'cors', credentials: 'omit' });
                           if (res.ok) return await res.blob();
                       } catch (e) {
                           console.log("Direct client fetch failed, attempting proxy fetch:", e);
                       }
                       
                       // Try our own proxy first
                       try {
                           const proxyUrl1 = `/api/proxy-download?url=${encodeURIComponent(url)}`;
                           const res1 = await fetch(proxyUrl1);
                           if (res1.ok) return await res1.blob();
                       } catch (e) {
                           console.log("Own proxy failed, falling back to allorigins:", e);
                       }
                       
                       // Fallback to allorigins
                       const proxyUrl2 = `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`;
                       const res2 = await fetch(proxyUrl2);
                       if (res2.ok) return await res2.blob();
                       throw new Error("Unable to fetch image content via proxy");
                   }
               }

               function triggerProxyDownload(url, filename) {
                    const form = document.createElement('form');
                    form.method = 'POST';
                    form.action = '/api/proxy-download';
                    form.target = '_self';
                    
                    const urlInput = document.createElement('input');
                    urlInput.type = 'hidden';
                    urlInput.name = 'url';
                    urlInput.value = url;
                    
                    form.appendChild(urlInput);
                    document.body.appendChild(form);
                    form.submit();
                    
                    setTimeout(() => {
                        document.body.removeChild(form);
                    }, 1000);
                }

               function triggerLocalDownload(blob, filename) {
                   const blobUrl = URL.createObjectURL(blob);
                   const a = document.createElement('a');
                   a.href = blobUrl;
                   a.download = filename;
                   a.target = '_self';
                   document.body.appendChild(a);
                   a.click();
                   setTimeout(() => {
                       document.body.removeChild(a);
                       URL.revokeObjectURL(blobUrl);
                   }, 1500);
               }

                              async function downloadImage(url) {
                   if (!url) return;
                   let ext = "jpg";
                   try {
                       const cleanUrl = url.split("?")[0];
                       const parts = cleanUrl.split(".");
                       if (parts.length > 1) {
                           const possibleExt = parts[parts.length - 1].toLowerCase();
                           if (["jpg", "jpeg", "png", "webp", "gif"].includes(possibleExt)) {
                               ext = possibleExt;
                           }
                       }
                   } catch(e) {}
                   const filename = `bexobd-${Date.now()}.${ext}`;
                   
                   showToast("ডাউনলোড শুরু হচ্ছে...", "success");

                   try {
                       const blob = await getSafeBlob(url);
                       triggerLocalDownload(blob, filename);
                   } catch (error) {
                       console.error("Download failed:", error);
                       showToast("ডাউনলোড ব্যর্থ হয়েছে!", "error");
                   }
               }

               window.closeDownloadSheet = function(sheetId) {
                   const sheet = document.getElementById(sheetId);
                   if (sheet) {
                       const content = sheet.querySelector('.bg-white');
                       if (content) {
                           content.classList.add('translate-y-full');
                       }
                       setTimeout(() => {
                           sheet.remove();
                       }, 300);
                   }
               };

