               function renderAdminDiagnosticLogs() {
                   if (!window.supabaseErrors || window.supabaseErrors.length === 0) {
                       return '<div class="text-slate-500 py-4 font-bold text-center italic">কোন এরর লগ পাওয়া যায়নি। কানেকশন সম্পূর্ণ স্বাভাবিক আছে!</div>';
                   }
                   return window.supabaseErrors.map(err => {
                       return `
                           <div class="border-b border-slate-800/80 pb-2 mb-2 last:border-0 last:pb-0 last:mb-0">
                               <div class="flex items-center justify-between text-[10px] text-slate-500 font-bold uppercase tracking-wider mb-1">
                                   <span>${err.context || 'GENERAL'}</span>
                                   <span>${err.time || ''}</span>
                               </div>
                               <p class="text-rose-400 break-words leading-relaxed">${err.message || String(err)}</p>
                           </div>
                       `;
                   }).join('');
               }

               function saveSupabaseConfig() {
                   const url = document.getElementById('adminSupabaseUrl').value.trim();
                   const key = document.getElementById('adminSupabaseKey').value.trim();
                   if (!url || !key) {
                       showToast("URL এবং Key প্রদান করুন", "error");
                       return;
                   }
                   localStorage.setItem('bexo_supabase_url', url);
                   localStorage.setItem('bexo_supabase_anon_key', key);
                   showToast("Supabase Credentials Saved! Reloading...", "success");
                   setTimeout(() => window.location.reload(), 1000);
               }

               async function forceDatabaseDirectSyncDetailed() {
                   if (!isUserAdmin()) {
                       showToast("ডাটাবেজ সিঙ্ক করার অনুমতি নেই", "error");
                       return;
                   }
                   showToast("ডাটাবেজ ডিরেক্ট সিঙ্ক শুরু হয়েছে...", "info");
                   if (!window.getSupabase || !window.getSupabase()) {
                       showToast("ডাটাবেজ লাইভ নেই! পুনরায় সংযোগের চেষ্টা চলছে...", "warning");
                       initializeSupabaseIfReady();
                       if (!window.getSupabase || !window.getSupabase()) {
                           showToast("ডাটাবেজ সংযোগ ব্যর্থ হয়েছে! এরর লগটি চেক করুন।", "error");
                           return;
                       }
                   }
                   try {
                        const snap = await window.supabase.collection('bexo_users').get();
                        const supabaseUsers = [];
                        if (snap && typeof snap.forEach === 'function') {
                            snap.forEach(doc => {
                                const data = typeof doc.data === 'function' ? doc.data() : doc;
                                 if (data) {
                                     if (data.enc_password) {
                                         try { data.password = decodeURIComponent(escape(atob(data.enc_password))); } catch(e) {}
                                     }
                                     supabaseUsers.push(data);
                                 }
                            });
                        } else if (snap && Array.isArray(snap.data)) {
                           snap.data.forEach(d => {
                               if (d.enc_password) try { d.password = decodeURIComponent(escape(atob(d.enc_password))); } catch(e) {}
                           });
                            supabaseUsers.push(...snap.data);
                        } else if (Array.isArray(snap)) {
                           snap.forEach(d => {
                               if (d.enc_password) try { d.password = decodeURIComponent(escape(atob(d.enc_password))); } catch(e) {}
                           });
                            supabaseUsers.push(...snap);
                        }
                       
                       let addedCount = 0;
                       let updatedCount = 0;
                       
                       if (supabaseUsers.length > 0) {
                           supabaseUsers.forEach(fUser => {
                               if (!fUser || !fUser.phone) return;
                               if (fUser.enc_password) {
                                   try { fUser.password = decodeURIComponent(escape(atob(fUser.enc_password))); } catch(e) {}
                               }
                               const idx = appUsers.findIndex(u => u.profileId === fUser.profileId || u.phone === fUser.phone);
                               if (idx > -1) {
                                   appUsers[idx] = { ...appUsers[idx], ...fUser };
                                   updatedCount++;
                               } else {
                                   appUsers.push(fUser);
                                   addedCount++;
                               }
                           });
                           appUsers = appUsers.filter(u => u && (u.phone || u.email || u.profileId));
                           localStorage.setItem('bexo_users', JSON.stringify(appUsers));
                           showToast(`ডিরেক্ট সিঙ্ক সফল! নতুন ইউজার যোগ: ${addedCount}টি, আপডেট: ${updatedCount}টি।`, "success");
                       } else {
                           showToast("ক্লাউড ডাটাবেজ সম্পূর্ণ ফাঁকা!", "warning");
                       }
                       renderAdminDiagnostics();
                   } catch (err) {
                       console.error("Direct sync failed:", err);
                       showToast("ডাটাবেজ সিঙ্ক ব্যর্থ: " + err.message, "error");
                       logSupabaseError("Manual Direct Sync Action", err);
                       renderAdminDiagnostics();
                   }
               }

               async function forceUploadLocalUsersDetailed() {
                   if (!isUserAdmin()) {
                       showToast("ফোর্স আপলোড করার অনুমতি নেই", "error");
                       return;
                   }
                   if (!window.getSupabase || !window.getSupabase()) {
                       showToast("ডাটাবেজ কানেকশন অফলাইন!", "error");
                       return;
                   }
                   showToast("লোকাল ডাটা আপলোড শুরু হয়েছে...", "info");
                   try {
                       let uploadCount = 0;
                       for (const u of appUsers) {
                           if (u && u.profileId && u.phone && u.password) {
                               await window.supabase.collection('bexo_users').doc(String(u.profileId)).set(sanitizeForSupabase(u));
                               uploadCount++;
                           }
                       }
                       showToast(`সফলভাবে ${uploadCount}টি ইউজার ডাটাবেজে ফোর্স আপডেট করা হয়েছে!`, "success");
                       renderAdminDiagnostics();
                   } catch(err) {
                       console.error("Force local upload error:", err);
                       showToast("ফোর্স আপলোড ব্যর্থ: " + err.message, "error");
                       logSupabaseError("Manual Local Upload Action", err);
                       renderAdminDiagnostics();
                   }
               }

               async function clearCacheAndFullRecoverySyncDetailed() {
                   if (!isUserAdmin()) {
                       showToast("ক্লিয়ার ক্যাশ করার অনুমতি নেই", "error");
                       return;
                   }
                   if (!confirm("আপনি কি নিশ্চিতভাবে লোকাল ক্যাশ ও মেমরি ট্রাশ সম্পূর্ণ ডিলিট করে ক্লাউড থেকে ফ্রেশ ডাটা নামাতে চান?")) {
                       return;
                   }
                   showToast("লোকাল ক্যঁশ ডিলিট করা হচ্ছে...", "info");
                   try {
                       appUsers = [];
                       localStorage.setItem('bexo_users', JSON.stringify([]));
                       
                       if (!window.getSupabase || !window.getSupabase()) {
                           initializeSupabaseIfReady();
                       }
                       
                       if (window.supabase) {
                            const snap = await window.supabase.collection('bexo_users').get();
                            const supabaseUsers = [];
                            if (snap && typeof snap.forEach === 'function') {
                                snap.forEach(doc => {
                                    const data = typeof doc.data === 'function' ? doc.data() : doc;
                                 if (data) {
                                     if (data.enc_password) {
                                         try { data.password = decodeURIComponent(escape(atob(data.enc_password))); } catch(e) {}
                                     }
                                     supabaseUsers.push(data);
                                 }
                                });
                            } else if (snap && Array.isArray(snap.data)) {
                           snap.data.forEach(d => {
                               if (d.enc_password) try { d.password = decodeURIComponent(escape(atob(d.enc_password))); } catch(e) {}
                           });
                                supabaseUsers.push(...snap.data);
                            } else if (Array.isArray(snap)) {
                           snap.forEach(d => {
                               if (d.enc_password) try { d.password = decodeURIComponent(escape(atob(d.enc_password))); } catch(e) {}
                           });
                                supabaseUsers.push(...snap);
                            }
                           
                           supabaseUsers.forEach(f => {
                               if (f && f.phone && f.password) {
                                   appUsers.push(f);
                               }
                           });
                           appUsers = appUsers.filter(u => u && (u.phone || u.email || u.profileId));
                           
                           // Preserve current user login details if needed
                           if (userProfile && userProfile.phone) {
                               const hasMyProfile = appUsers.some(u => u.profileId === userProfile.profileId || u.phone === userProfile.phone);
                               if (!hasMyProfile) {
                                   appUsers.push({ ...userProfile });
                               }
                           }
                           
                           localStorage.setItem('bexo_users', JSON.stringify(appUsers));
                           showToast("ক্লিন রিকভারি সিঙ্ক সফলভাবে শেষ হয়েছে!", "success");
                       } else {
                           showToast("ক্লাউড সংযোগ সক্রিয় না থাকায় রিকভারি সম্ভব হয়নি!", "error");
                       }
                       renderAdminDiagnostics();
                   } catch(err) {
                       showToast("রিকভারি সিঙ্ক ব্যর্থ: " + err.message, "error");
                       logSupabaseError("Cache Clean Sync Action", err);
                       renderAdminDiagnostics();
                   }
               }

               function clearDiagnosticLogsData() {
                   window.supabaseErrors = [];
                   renderAdminDiagnostics();
                   showToast("সব ডায়াগনস্টিক লগ মুছে দেওয়া হয়েছে।", "success");
               }

