              // Handlers for API Import
              window.saveApiSettings = async function() {
                  const baseUrl = document.getElementById('apiBaseUrl').value.trim();
                  const authType = document.getElementById('apiAuthType').value;
                  const apiKey = document.getElementById('apiKey').value.trim();
                  const secretKey = document.getElementById('apiSecretKey').value.trim();
                  
                  if (!appSettings.apiIntegration) appSettings.apiIntegration = {};
                  appSettings.apiIntegration.baseUrl = baseUrl;
                  appSettings.apiIntegration.authType = authType;
                  appSettings.apiIntegration.apiKey = apiKey;
                  appSettings.apiIntegration.secretKey = secretKey;
                  
                  saveAppSettings();
                  
                  try {
                      await fetch('/api/save-settings', {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify(appSettings.apiIntegration)
                      });
                  } catch (e) {
                      console.error("Backend save settings error", e);
                  }
                  
                  showToast("API Settings Saved!", "success");
              };
              
              function prepareApiRequestOptions(baseUrl, endpoint) {
                  const api = appSettings.apiIntegration || {};
                  let url = baseUrl;
                  if (!url.endsWith('/') && !endpoint.startsWith('/')) {
                      url += '/';
                  }
                  url += endpoint;
                  
                  const options = {
                      method: 'GET',
                      headers: {
                          'Accept': 'application/json'
                      }
                  };
                  
                  if (api.authType === 'bearer' && api.apiKey) {
                      options.headers['Authorization'] = 'Bearer ' + api.apiKey;
                  } else if (api.authType === 'query' && api.apiKey) {
                      const separator = url.includes('?') ? '&' : '?';
                      url += separator + 'api_key=' + encodeURIComponent(api.apiKey);
                      if (api.secretKey) {
                          url += '&secret_key=' + encodeURIComponent(api.secretKey);
                      }
                  } else if (api.authType === 'custom_headers') {
                      if (api.apiKey) options.headers['api-key'] = api.apiKey;
                      if (api.secretKey) options.headers['secret-key'] = api.secretKey;
                      if (api.apiKey) options.headers['X-Api-Key'] = api.apiKey;
                      if (api.secretKey) options.headers['X-Secret-Key'] = api.secretKey;
                      if (api.apiKey) options.headers['client_id'] = api.apiKey;
                      if (api.secretKey) options.headers['client_secret'] = api.secretKey;
                  } else if (api.authType === 'basic' && (api.apiKey || api.secretKey)) {
                      options.headers['Authorization'] = 'Basic ' + btoa(api.apiKey + ':' + api.secretKey);
                  }
                  
                  return { url, options };
              }

              window.testApiConnection = async function() {
                  window.saveApiSettings(); // Save first
                  
                  const api = appSettings.apiIntegration;
                  if (!api.baseUrl) {
                      return showToast("Please enter Base URL", "error");
                  }
                  
                  showToast("Testing connection...", "info");
                  
                  try {
                      const response = await fetch('/api/test-connection', {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify({
                              baseUrl: api.baseUrl,
                              authType: api.authType,
                              apiKey: api.apiKey,
                              secretKey: api.secretKey
                          })
                      });
                      
                      const data = await response.json();
                      
                      if (response.ok && data.success) {
                          appSettings.apiIntegration.status = 'Connected';
                          saveAppSettings();
                          showToast(data.message || "Connection Successful!", "success");
                          
                          const badge = document.getElementById('apiStatusBadge');
                          if (badge) {
                              badge.className = "px-4 py-2 rounded-xl text-xs font-bold bg-emerald-50 text-emerald-600 flex items-center gap-2";
                              badge.innerHTML = '<span class="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span> Connected';
                          }
                          const fetchBtn = document.getElementById('fetchDataBtn');
                          if (fetchBtn) {
                              fetchBtn.disabled = false;
                              fetchBtn.classList.remove('opacity-50', 'cursor-not-allowed');
                          }
                      } else {
                          throw new Error(data.error || `Status ${response.status}`);
                      }
                  } catch (err) {
                      console.error("API Test Error:", err);
                      appSettings.apiIntegration.status = 'Failed';
                      saveAppSettings();
                      showToast("Connection Failed: " + err.message, "error");
                      
                      const badge = document.getElementById('apiStatusBadge');
                      if (badge) {
                          badge.className = "px-4 py-2 rounded-xl text-xs font-bold bg-rose-50 text-rose-600 flex items-center gap-2";
                          badge.innerHTML = '<span class="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></span> Failed';
                      }
                  }
              };

              window.saveApiMarkup = function() {
                  const markup = parseFloat(document.getElementById('apiMarkup').value) || 0;
                  const fixedMarkup = parseFloat(document.getElementById('apiFixedMarkup').value) || 0;
                  appSettings.apiMarkup = markup;
                  appSettings.apiFixedMarkup = fixedMarkup;
                  saveAppSettings();
                  showToast("Bulk Markup Applied!", "success");
                  
                  // Update UI if products are currently displayed
                  if (window.fetchedApiProducts && window.fetchedApiProducts.length > 0) {
                      renderFetchedProducts(window.fetchedApiProducts);
                  }
              };
              
              window.fetchedApiProducts = [];

              window.fetchApiProducts = async function() {
                  const endpoint = document.getElementById('importEndpoint').value.trim() || '/products';
                  const api = appSettings.apiIntegration;
                  
                  if (!api || api.status !== 'Connected') {
                      return showToast("Please test connection successfully first.", "error");
                  }
                  
                  const list = document.getElementById('apiProductPreviewList');
                  if (list) {
                      list.innerHTML = `
                          <div class="p-12 text-center flex flex-col items-center justify-center">
                              <div class="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600 mb-4"></div>
                              <p class="text-slate-400 font-bold text-sm">Contacting API via backend proxy and fetching products...</p>
                          </div>
                      `;
                  }
                  
                  try {
                      const response = await fetch('/api/import-products', {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify({
                              baseUrl: api.baseUrl,
                              endpoint: endpoint,
                              authType: api.authType,
                              apiKey: api.apiKey,
                              secretKey: api.secretKey
                          })
                      });
                      
                      const data = await response.json();
                      
                      if (!response.ok || !data.success) {
                          throw new Error(data.error || `HTTP ${response.status}`);
                      }
                      
                      window.fetchedApiProducts = data.products || [];
                      
                      renderFetchedProducts(window.fetchedApiProducts);
                      showToast(`Found ${window.fetchedApiProducts.length} products!`, "success");
                      
                  } catch (err) {
                      console.error("Fetch API Error:", err);
                      if (list) {
                          list.innerHTML = `
                              <div class="p-12 text-center flex flex-col items-center justify-center">
                                  <div class="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center text-rose-500 mb-4">
                                      <i class="fas fa-exclamation-triangle text-2xl"></i>
                                  </div>
                                  <p class="text-slate-800 font-bold text-sm">Failed to fetch products</p>
                                  <p class="text-slate-500 text-xs mt-2 max-w-md">${err.message}</p>
                              </div>
                          `;
                      }
                  }
              };

              function renderFetchedProducts(products) {
                  const list = document.getElementById('apiProductPreviewList');
                  if (!list) return;
                  
                  if (products.length === 0) {
                      list.innerHTML = `
                          <div class="p-12 text-center flex flex-col items-center justify-center">
                              <p class="text-slate-400 font-bold text-sm">No products found in response.</p>
                          </div>
                      `;
                      return;
                  }
                  
                  const markup = parseFloat(appSettings.apiMarkup) || 0;
                  const fixedMarkup = parseFloat(appSettings.apiFixedMarkup) || 0;
                  
                  let html = '';
                  products.forEach((p, index) => {
                      // Calculate final price based on rules
                      let markupAmount = p.sourcePrice * (markup / 100);
                      let finalPrice = p.sourcePrice + markupAmount + fixedMarkup;
                      
                      html += `
                          <div class="p-4 grid grid-cols-12 gap-4 items-center hover:bg-slate-50 transition-all border-b border-slate-50 last:border-0">
                              <div class="col-span-1 text-center">
                                  <input type="checkbox" data-index="${index}" class="rounded text-orange-600 focus:ring-orange-500 h-4 w-4 api-prod-cb">
                              </div>
                              <div class="col-span-2">
                                  <img src="${p.img || 'https://via.placeholder.com/150'}" class="w-12 h-12 rounded-xl object-cover border border-slate-200">
                              </div>
                              <div class="col-span-4">
                                  <p class="text-sm font-bold text-slate-800 line-clamp-1">${p.name}</p>
                                  <p class="text-[10px] text-slate-500 font-bold mt-1">SKU: ${p.sku || 'N/A'}</p>
                              </div>
                              <div class="col-span-3">
                                  <select class="w-full text-xs font-bold p-1 bg-white border border-slate-200 rounded api-prod-cat" data-index="${index}">
                                      <option value="${p.category}">${p.category}</option>
                                      <!-- Map to local categories if needed -->
                                  </select>
                                  <p class="text-[10px] text-slate-500 font-bold mt-1">Stock: <span class="${p.stock > 0 ? 'text-emerald-600' : 'text-rose-600'}">${p.stock}</span></p>
                              </div>
                              <div class="col-span-2 text-right">
                                  <p class="text-[10px] text-slate-400 line-through">৳${p.sourcePrice.toFixed(2)}</p>
                                  <p class="text-sm font-black text-emerald-600">৳${finalPrice.toFixed(2)}</p>
                              </div>
                          </div>
                      `;
                  });
                  list.innerHTML = html;
              }
              
              window.toggleAllApiProducts = function(cb) {
                  const checkboxes = document.querySelectorAll('.api-prod-cb');
                  checkboxes.forEach(c => c.checked = cb.checked);
              };
              
              window.publishSelectedProducts = async function() {
                  const checkboxes = document.querySelectorAll('.api-prod-cb:checked');
                  if (checkboxes.length === 0) {
                      return showToast("Please select at least one product.", "warning");
                  }
                  
                  if (!confirm(`Are you sure you want to publish ${checkboxes.length} products to the catalog?`)) {
                      return;
                  }
                  
                  const btn = event.currentTarget;
                  const originalText = btn.innerHTML;
                  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Publishing via Backend...';
                  btn.disabled = true;
                  
                  const markup = parseFloat(appSettings.apiMarkup) || 0;
                  const fixedMarkup = parseFloat(appSettings.apiFixedMarkup) || 0;
                  
                  // Collect selected products from UI
                  const selectedProducts = [];
                  for (let i = 0; i < checkboxes.length; i++) {
                      const index = checkboxes[i].getAttribute('data-index');
                      const p = window.fetchedApiProducts[index];
                      // Get possibly updated category
                      const catSelect = document.querySelector(`.api-prod-cat[data-index="${index}"]`);
                      if (catSelect) p.category = catSelect.value;
                      selectedProducts.push(p);
                  }
                  
                  try {
                      // We call the backend to format them properly
                      const response = await fetch('/api/publish-products', {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify({
                              selectedProducts: selectedProducts,
                              markupValue: markup > 0 ? markup : (fixedMarkup > 0 ? fixedMarkup : 0),
                              markupType: markup > 0 ? 'percentage' : (fixedMarkup > 0 ? 'fixed' : 'none')
                          })
                      });
                      
                      const data = await response.json();
                      if (!response.ok || !data.success) {
                          throw new Error(data.error || "Backend publishing failed");
                      }
                      
                      const newPosts = data.products;
                      
                      appPosts.unshift(...newPosts);
                      if (typeof savePosts === 'function') savePosts();
                      
                      // Save to Supabase via frontend
                      if (window.getSupabase && window.getSupabase()) {
                          newPosts.forEach(postData => {
                              window.supabase.collection('bexo_posts').doc(String(postData.id)).set(sanitizeForSupabase(postData))
                                  .catch(err => console.warn("Supabase save post error:", err));
                          });
                      }
                      
                      showToast(`Successfully published ${newPosts.length} products!`, "success");
                      
                      // Refresh product list in background if possible
                      if (typeof syncProductsFromDatabaseSilently === 'function') syncProductsFromDatabaseSilently();
                      
                      // Clear list
                      document.getElementById('apiProductPreviewList').innerHTML = `
                          <div class="p-12 text-center flex flex-col items-center justify-center">
                              <div class="w-16 h-16 bg-emerald-50 rounded-full flex items-center justify-center text-emerald-500 mb-4">
                                  <i class="fas fa-check-circle text-2xl"></i>
                              </div>
                              <p class="text-slate-800 font-bold text-sm">Published ${newPosts.length} Products to Catalog</p>
                          </div>
                      `;
                      
                  } catch (err) {
                      console.error("Error publishing products:", err);
                      showToast("Failed to publish: " + err.message, "error");
                  } finally {
                      btn.innerHTML = originalText;
                      btn.disabled = false;
                  }
              };

