              function systemPurgeAllData() {
                  if (!confirm("আপনি কি নিশ্চিত? এটি আপনার ব্রাউজারের সমস্ত লোকাল ডাটা ডিলিট করে দেবে এবং তা ফিরে পাওয়া যাবে না।")) return;
                  
                  const keysToPurge = [
                      'bexo_users', 'bexo_orders', 'bexo_posts', 'bexo_transactions', 
                      'bexo_profile', 'bexo_settings', 'bexo_premium_requests', 
                      'bexo_recharge_requests', 'bexo_balance_requests', 'bexo_bill_requests',
                      'bexo_pending_profits', 'bexo_customer_reports', 'bexo_categories',
                      'bexo_accounts', 'bexo_withdrawals', 'bexo_support_tickets'
                  ];
                  
                  keysToPurge.forEach(key => localStorage.removeItem(key));
                  
                  alert("সফলভাবে রিসেট সম্পন্ন হয়েছে। পেইজটি রিলোড হচ্ছে...");
                  location.reload();
              }

              function saveAdminSettings() {
                  appSettings.homeBannerUrl = document.getElementById('setupBannerUrl').value;
                  appSettings.youtubeLink = document.getElementById('setupYoutube').value;
                  appSettings.premiumGroupLink = document.getElementById('setupPremiumGroup').value;
                  appSettings.bkashNumber = document.getElementById('setupBkash').value;
                  appSettings.nagadNumber = document.getElementById('setupNagad').value;
                  appSettings.mcashNumber = document.getElementById('setupMcash').value;
                  
                  appSettings.dhakaCharge = parseInt(document.getElementById('setupDhakaCharge').value) || 0;
                  appSettings.outsideDhakaCharge = parseInt(document.getElementById('setupOutsideDhakaCharge').value) || 0;
                  
                  // Saved merged configs
                  appSettings.refJoiningBonus = parseInt(document.getElementById('refJoiningBonus').value) || 0;
                  appSettings.minWithdraw = parseInt(document.getElementById('minWithdrawLimit').value) || 500;

                  // Save admin password reset if set
                  const newPass = document.getElementById('newAdminPass').value.trim();
                  if (newPass.length > 0) {
                      if (newPass.length < 4) {
                          showToast("পাসওয়ার্ড কমপক্ষে ৪ অক্ষরের হতে হবে!", "warning");
                          return;
                      }
                      localStorage.setItem('bexo_admin_pass', newPass);
                  }

                  saveAppSettings();
                  showToast('সেটিংস সফলভাবে সংরক্ষিত হয়েছে!', 'success');
                  renderAdminAppSettings();
              }

