              function savePassiveConfig() {
                  appSettings.refJoiningBonus = parseInt(document.getElementById('refJoiningBonus').value) || 0;
                  appSettings.minWithdraw = parseInt(document.getElementById('minWithdrawLimit').value) || 500;
                  saveAppSettings();
                  showToast("সেটিংস সেভ হয়েছে!", "success");
              }



              function renderAdminBills() {
                  window.activeFinanceTab = 'bills';
                  renderAdminWithdrawalList();
              }

              function updateBillStatus(profileId, internalId, newStatus, trxId = '', adminNote = '') {
                  const reqIdx = appBillRequests.findIndex(r => r.id === internalId);
                  if(reqIdx === -1) return;

                  const req = appBillRequests[reqIdx];
                  req.status = newStatus;
                  if (trxId) req.trxId = trxId;
                  if (adminNote) req.adminNote = adminNote;
                  saveBillRequests();

                  // 1. Direct Supabase user document update to guarantee reliability
                  if (window.supabase && profileId) {
                      const userDocRef = window.supabase.collection('bexo_users').doc(String(profileId));
                      userDocRef.get().then(doc => {
                          if (doc.exists) {
                              const userData = doc.data();
                              if (!userData.rechargeTransactions) userData.rechargeTransactions = [];
                              const tx = userData.rechargeTransactions.find(t => t.id === internalId);
                              if (tx) {
                                  tx.status = newStatus;
                                  if (trxId) tx.trxId = trxId;
                                  if (adminNote) tx.adminNote = adminNote;
                                  
                                  if (newStatus === 'Rejected') {
                                      userData.rechargeBalance = (Number(userData.rechargeBalance) || 0) + (Number(tx.amount) || 0);
                                      userData.balance = userData.rechargeBalance;
                                  }
                              }
                              userDocRef.set(sanitizeForSupabase(userData))
                                  .then(() => console.log(`[Supabase] Directly updated user ${profileId} bill status in Supabase.`))
                                  .catch(err => console.error("Error setting user doc in updateBillStatus:", err));
                          }
                      }).catch(err => console.error("Error direct getting user doc in updateBillStatus:", err));
                  }

                  // 2. Local appUsers update for immediate UI refresh
                  const uIdx = appUsers.findIndex(u => u.profileId === profileId);
                  if (uIdx > -1) {
                      const targetUser = appUsers[uIdx];
                      if (!targetUser.rechargeTransactions) targetUser.rechargeTransactions = [];
                      const tx = targetUser.rechargeTransactions.find(t => t.id === internalId);
                      if (tx) {
                          tx.status = newStatus;
                          if (trxId) tx.trxId = trxId;
                          if (adminNote) tx.adminNote = adminNote;
                          
                          if (newStatus === 'Rejected') {
                              targetUser.rechargeBalance = (Number(targetUser.rechargeBalance) || 0) + (Number(tx.amount) || 0);
                              targetUser.balance = targetUser.rechargeBalance;
                              
                              // Log refund/fail to global appTransactions
                              appTransactions.unshift({
                                  id: Date.now(),
                                  date: new Date().toLocaleString(),
                                  userId: targetUser.id || targetUser.profileId,
                                  profileId: targetUser.profileId,
                                  details: `রিফান্ড: বিল পরিশোধ রিকোয়েস্ট বাতিল/ব্যর্থ (৳${tx.amount})`,
                                  amount: Number(tx.amount),
                                  balance: targetUser.rechargeBalance
                              });
                              saveTransactions();
                          } else if (newStatus === 'Successful') {
                              // Log successful bill payment out of wallet path
                              appTransactions.unshift({
                                  id: Date.now(),
                                  date: new Date().toLocaleString(),
                                  userId: targetUser.id || targetUser.profileId,
                                  profileId: targetUser.profileId,
                                  details: `বিল পরিশোধ সফল (ID: ${internalId})`,
                                  amount: -Number(tx.amount),
                                  balance: targetUser.rechargeBalance,
                                  trxId: trxId,
                                  adminNote: adminNote
                              });
                              saveTransactions();
                          }
                      }
                      
                      if (targetUser.profileId === userProfile.profileId) {
                          userProfile.rechargeBalance = targetUser.rechargeBalance;
                          userProfile.balance = targetUser.rechargeBalance;
                          userProfile.rechargeTransactions = targetUser.rechargeTransactions;
                          saveProfile();
                          updateHeaderBalance();
                      }
                      saveUsers(profileId, true);
                  }

                  renderAdminBills();
                  updateAdminStats();
                  showToast(`বিল পেমেন্ট রিকোয়েস্ট ${newStatus === 'Successful' ? 'সফলভাবে অ্যাপ্রুভ' : 'বাতিল'} করা হয়েছে।`, "success");
              }

              function updateRechargeStatus(profileId, internalId, newStatus, trxId = '', adminNote = '') {
                  const gReq = (appRechargeRequests || []).find(r => r.id === internalId && r.profileId === profileId);
                  if(gReq) {
                      gReq.status = newStatus;
                      if (trxId) gReq.trxId = trxId;
                      if (adminNote) gReq.adminNote = adminNote;
                  }
                  saveRechargeRequests();

                  // 1. Direct Supabase user document update to guarantee reliability
                  if (window.supabase && profileId) {
                      const userDocRef = window.supabase.collection('bexo_users').doc(String(profileId));
                      userDocRef.get().then(doc => {
                          if (doc.exists) {
                              const userData = doc.data();
                              if (!userData.rechargeTransactions) userData.rechargeTransactions = [];
                              const tx = userData.rechargeTransactions.find(t => t.id === internalId);
                              if (tx) {
                                  tx.status = newStatus;
                                  if (trxId) tx.trxId = trxId;
                                  if (adminNote) tx.adminNote = adminNote;
                                  
                                  if (newStatus === 'Rejected') {
                                      userData.rechargeBalance = (Number(userData.rechargeBalance) || 0) + (Number(tx.amount) || 0);
                                      userData.balance = userData.rechargeBalance;
                                  }
                              }
                              userDocRef.set(sanitizeForSupabase(userData))
                                  .then(() => console.log(`[Supabase] Directly updated user ${profileId} recharge status in Supabase.`))
                                  .catch(err => console.error("Error setting user doc in updateRechargeStatus:", err));
                          }
                      }).catch(err => console.error("Error direct getting user doc in updateRechargeStatus:", err));
                  }

                  // 2. Local appUsers update for immediate UI refresh
                  const uIdx = appUsers.findIndex(u => u.profileId === profileId);
                  if (uIdx > -1) {
                      const targetUser = appUsers[uIdx];
                      if (!targetUser.rechargeTransactions) targetUser.rechargeTransactions = [];
                      const tx = targetUser.rechargeTransactions.find(t => t.id === internalId);
                      if (tx) {
                          tx.status = newStatus;
                          if (trxId) tx.trxId = trxId;
                          if (adminNote) tx.adminNote = adminNote;
                          
                          if (newStatus === 'Rejected') {
                              targetUser.rechargeBalance = (Number(targetUser.rechargeBalance) || 0) + (Number(tx.amount) || 0);
                              targetUser.balance = targetUser.rechargeBalance;
                              
                              // Log recharge refund to global appTransactions
                              appTransactions.unshift({
                                  id: Date.now(),
                                  date: new Date().toLocaleString(),
                                  userId: targetUser.id || targetUser.profileId,
                                  profileId: targetUser.profileId,
                                  details: `রিফান্ড: রিচার্জ রিকোয়েস্ট বাতিল/পেমেন্ট ফেল (৳${tx.amount})`,
                                  amount: Number(tx.amount),
                                  balance: targetUser.rechargeBalance
                              });
                              saveTransactions();
                          } else if (newStatus === 'Successful') {
                              // Log successful recharge transaction to global path
                              appTransactions.unshift({
                                  id: Date.now(),
                                  date: new Date().toLocaleString(),
                                  userId: targetUser.id || targetUser.profileId,
                                  profileId: targetUser.profileId,
                                  details: `মোবাইল রিচার্জ সফল (ID: ${internalId})`,
                                  amount: -Number(tx.amount),
                                  balance: targetUser.rechargeBalance,
                                  trxId: trxId,
                                  adminNote: adminNote
                              });
                              saveTransactions();
                          }
                      }
                      
                      if (targetUser.profileId === userProfile.profileId) {
                          userProfile.rechargeBalance = targetUser.rechargeBalance;
                          userProfile.balance = targetUser.rechargeBalance;
                          userProfile.rechargeTransactions = targetUser.rechargeTransactions;
                          saveProfile();
                          updateHeaderBalance();
                      }
                      saveUsers(profileId, true);
                  }

                  renderAdminRechargeList();
                  updateAdminStats();
                  showToast(`মোবাইল রিচার্জ রিকোয়েস্ট ${newStatus === 'Successful' ? 'সফলভাবে অ্যাপ্রুভ' : 'বাতিল'} করা হয়েছে।`, "success");
              }

              function updateWithdrawStatus(id, newStatus, trxId = '', adminNote = '') {
                  const idx = appWithdrawals.findIndex(w => w.id === id);
                  if(idx === -1) return;

                  const req = appWithdrawals[idx];
                  // Standardize: If admin rejects/cancels, we set status to 'Cancelled'
                  const statusToSet = (newStatus === 'Rejected' || newStatus === 'Cancelled') ? 'Cancelled' : newStatus;

                  // Keep local memory array in sync immediately
                  req.status = statusToSet;
                  if (trxId) req.trxId = trxId;
                  if (adminNote) req.adminNote = adminNote;
                  saveWithdrawals();

                  // 1. Run standard Supabase database transaction for multi-document reliability
                  if (window.supabase && req.profileId) {
                      const userDocRef = window.supabase.collection('bexo_users').doc(String(req.profileId));
                      const withdrawDocRef = window.supabase.collection('bexo_withdrawals').doc(String(id));

                      window.supabase.runTransaction(async (transaction) => {
                          const userDoc = await transaction.get(userDocRef);
                          const withdrawDoc = await transaction.get(withdrawDocRef);

                          let currentDbStatus = 'Pending';
                          if (withdrawDoc.exists) {
                              currentDbStatus = withdrawDoc.data().status || 'Pending';
                          }

                          // CRITICAL DOUBLE-SPENDING PREVENTION:
                          if (currentDbStatus === 'Completed' || currentDbStatus === 'Cancelled' || currentDbStatus === 'Rejected') {
                              throw new Error(`উইথড্র রিকোয়েস্টটি ইতিমধ্যে প্রসেস করা হয়েছে! (Status: ${currentDbStatus})`);
                          }

                          if (userDoc.exists) {
                              const currentUsrData = userDoc.data();
                              const currentBalance = Number(currentUsrData.rechargeBalance) || 0;
                              const amount = Number(req.amount) || 0;

                              let previousBalance = currentBalance;
                              let newBalance = currentBalance;

                              // If status updated to Completed, deduct balance now
                              if (statusToSet === 'Completed') {
                                  newBalance = currentBalance - amount;
                                  currentUsrData.rechargeBalance = newBalance;
                                  currentUsrData.balance = newBalance;
                              }

                              // Sync the inner rechargeTransactions of target user
                              if (!currentUsrData.rechargeTransactions) currentUsrData.rechargeTransactions = [];
                              const innerTx = currentUsrData.rechargeTransactions.find(t => String(t.id).includes(id) || (t.details && t.details.includes(id)));
                              if (innerTx) {
                                  innerTx.status = statusToSet;
                                  if (trxId) innerTx.trxId = trxId;
                                  if (adminNote) innerTx.adminNote = adminNote;
                              } else {
                                  currentUsrData.rechargeTransactions.unshift({
                                      id: id,
                                      type: 'Withdrawal',
                                      details: statusToSet === 'Cancelled' ? `উইথড্র রিকোয়েস্ট বাতিল (ID: ${id})` : `উইথড্র রিকোয়েস্ট সফল (ID: ${id})`,
                                      amount: statusToSet === 'Cancelled' ? 0 : -amount,
                                      status: statusToSet,
                                      adminNote: adminNote,
                                      time: new Date().toLocaleString('en-GB')
                                  });
                              }

                              // Write user updates back
                              transaction.set(userDocRef, sanitizeForSupabase(currentUsrData));

                              // Update main withdrawal state inside transaction
                              const updatedWd = {
                                  ...req,
                                  status: statusToSet,
                                  trxId: trxId,
                                  adminNote: adminNote
                              };
                              transaction.set(withdrawDocRef, sanitizeForSupabase(updatedWd));

                              // Write Audit/Transaction Log Entry to bexo_transactions
                              const auditTxnId = 'TXN-' + Date.now().toString() + '-' + Math.floor(1000 + Math.random() * 9000);
                              const auditTxn = {
                                  id: auditTxnId,
                                  date: new Date().toLocaleString('en-GB'),
                                  timestamp: Date.now(),
                                  userId: currentUsrData.id || currentUsrData.profileId || req.profileId,
                                  profileId: req.profileId,
                                  fullName: currentUsrData.fullName || 'User',
                                  type: statusToSet === 'Cancelled' ? 'Refund/Cancellation' : 'Withdrawal',
                                  amount: amount,
                                  previousBalance: previousBalance,
                                  newBalance: newBalance,
                                  status: statusToSet === 'Cancelled' ? 'Cancelled' : 'Success',
                                  trxId: trxId || id,
                                  adminEmail: (userProfile && userProfile.email) ? userProfile.email : 'admin@bexo.com',
                                  adminNote: adminNote,
                                  details: statusToSet === 'Cancelled' ? `উইথড্র রিকোয়েস্ট বাতিল এবং রিফান্ড (উইথড্র ID: ${id})` : `উইথড্র রিকোয়েস্ট সফলভাবে সম্পন্ন হয়েছে (উইথড্র ID: ${id})`
                              };
                              const auditTxnRef = window.supabase.collection('bexo_transactions').doc(String(auditTxnId));
                              transaction.set(auditTxnRef, sanitizeForSupabase(auditTxn));
                          }
                      }).then(() => {
                          console.log("[Supabase Transaction] Withdrawal updated successfully.");
                          if (typeof showToast === 'function') {
                              showToast(`উইথড্র রিকোয়েস্ট ${statusToSet === 'Completed' ? 'সম্পন্ন' : 'বাতিল ও রিফান্ড'} করা হয়েছে।`, "success");
                          }
                          syncUsersFromDatabaseSilently();
                      }).catch(err => {
                          console.error("[Supabase Transaction] Withdrawal flow failed:", err);
                          alert("লেনদেন প্রসেস করতে ব্যর্থ হয়েছে: " + err.message);
                      });
                  }

                  // 2. Local appUsers memory state sync for instant feedback
                  const uIdx = appUsers.findIndex(u => u.profileId === req.profileId);
                  if (uIdx > -1) {
                      const targetUser = appUsers[uIdx];
                      if (!targetUser.rechargeTransactions) targetUser.rechargeTransactions = [];
                      
                      const tx = targetUser.rechargeTransactions.find(t => String(t.id).includes(id) || (t.details && t.details.includes(id)));
                      if (tx) {
                          tx.status = statusToSet;
                          if (trxId) tx.trxId = trxId;
                          if (adminNote) tx.adminNote = adminNote;
                      }

                      if (statusToSet === 'Cancelled') {
                          // No balance change on cancel since it wasn't deducted
                          const oldBalance = Number(targetUser.rechargeBalance) || 0;
                          
                          appTransactions.unshift({
                              id: Date.now(),
                              date: new Date().toLocaleString(),
                              timestamp: Date.now(),
                              userId: targetUser.id || targetUser.profileId,
                              profileId: targetUser.profileId,
                              fullName: targetUser.fullName || 'User',
                              type: 'Refund/Cancellation',
                              amount: 0,
                              previousBalance: oldBalance,
                              newBalance: oldBalance,
                              status: 'Cancelled',
                              details: `উইথড্র রিকোয়েস্ট বাতিল/ব্যর্থ (ID: ${id}, ৳${req.amount})`,
                              trxId: trxId,
                              adminNote: adminNote,
                              adminEmail: (userProfile && userProfile.email) ? userProfile.email : 'admin@bexo.com'
                          });
                          saveTransactions();
                      } else if (statusToSet === 'Completed') {
                          const oldBalance = Number(targetUser.rechargeBalance) || 0;
                          const newBal = oldBalance - Number(req.amount);
                          
                          targetUser.rechargeBalance = newBal;
                          targetUser.balance = newBal;

                          appTransactions.unshift({
                              id: Date.now(),
                              date: new Date().toLocaleString(),
                              timestamp: Date.now(),
                              userId: targetUser.id || targetUser.profileId,
                              profileId: targetUser.profileId,
                              fullName: targetUser.fullName || 'User',
                              type: 'Withdrawal',
                              amount: Number(req.amount),
                              previousBalance: oldBalance,
                              newBalance: newBal,
                              status: 'Success',
                              details: `উইথড্র রিকোয়েস্ট সফল (ID: ${id}, ৳${req.amount})`,
                              trxId: trxId,
                              adminNote: adminNote,
                              adminEmail: (userProfile && userProfile.email) ? userProfile.email : 'admin@bexo.com'
                          });
                          saveTransactions();
                      }
                      
                      if (targetUser.profileId === userProfile.profileId) {
                          userProfile.rechargeBalance = targetUser.rechargeBalance;
                          userProfile.balance = targetUser.rechargeBalance;
                          userProfile.rechargeTransactions = targetUser.rechargeTransactions;
                          saveProfile();
                          updateHeaderBalance();
                      }
                      saveUsers(req.profileId, true);
                  }

                  renderAdminWithdrawalList();
                  updateAdminStats();
                  showToast(`উইথড্র রিকোয়েস্ট ${statusToSet === 'Completed' ? 'সফলভাবে সম্পন্ন' : 'বাতিল'} করা হয়েছে।`, "success");
              }

              function renderAdminRequests() {
                  const list = document.getElementById('adminRequestList');
                  if(!list) return;

                  list.innerHTML = appPremiumRequests.map(req => `
                      <tr class="border-b border-white/5 hover:bg-white/5 transition-colors">
                          <td class="p-4 font-mono font-bold">${req.profileId}</td>
                          <td class="p-4">${req.method}</td>
                          <td class="p-4">${req.lastDigits}</td>
                          <td class="p-4 text-xs font-mono">${req.trxId}</td>
                          <td class="p-4">
                              <span class="px-2 py-1 rounded text-[10px] font-bold ${req.status === 'active' ? 'bg-emerald-500/20 text-emerald-500' : 'bg-orange-500/20 text-orange-500'}">
                                  ${req.status.toUpperCase()}
                              </span>
                          </td>
                          <td class="p-4 text-right">
                              ${req.status === 'pending' ? `
                                  <button onclick="activateProfileById('${req.profileId}', ${req.id})" class="px-3 py-1 bg-emerald-600 rounded text-xs font-bold hover:bg-emerald-700">Activate</button>
                              ` : '<span class="text-xs text-slate-500">Completed</span>'}
                          </td>
                      </tr>
                  `).join('');
              }

              function activateProfileById(profileId, requestId) {
                  // Update request status
                  const req = appPremiumRequests.find(r => r.id === requestId);
                  if(req) req.status = 'active';

                  // Update target user plan locally in appUsers
                  const uIdx = appUsers.findIndex(u => u.profileId === profileId);
                  if (uIdx > -1) {
                      appUsers[uIdx].isPremium = true;
                      appUsers[uIdx].currentPlan = 'Premium Member';
                      saveUsers(profileId, true);
                  }

                  // Write directly to Supabase to update the target user Profile
                  if (window.supabase && profileId) {
                      const userDocRef = window.supabase.collection('bexo_users').doc(String(profileId));
                      userDocRef.get().then(doc => {
                          if (doc.exists) {
                              const userData = doc.data();
                              userData.isPremium = true;
                              userData.currentPlan = 'Premium Member';
                              userDocRef.set(sanitizeForSupabase(userData))
                                  .then(() => console.log(`[Supabase] Successfully activated premium user ${profileId}`))
                                  .catch(err => console.error("Error setting user doc in activateProfileById:", err));
                          }
                      }).catch(err => console.error("Error getting user doc in activateProfileById:", err));
                  }

                  if(userProfile.profileId === profileId) {
                      userProfile.isPremium = true;
                      userProfile.currentPlan = 'Premium Member';
                      saveProfile();
                  }

                  alert(`Profile ${profileId} activated successfully!`);

                  savePremiumRequests();
                  renderAdminRequests();
                  updateAdminStats();
              }

              function searchAndActivateProfile() {
                  const id = document.getElementById('adminIdSearch').value.trim();
                  if(!id) return;

                  if(userProfile.profileId === id) {
                      userProfile.isPremium = true;
                      userProfile.currentPlan = 'Premium Member';
                      saveProfile();
                      alert(`${id} has been activated!`);
                  } else {
                      // Update locally
                      const uIdx = appUsers.findIndex(u => u.profileId === id);
                      if (uIdx > -1) {
                          appUsers[uIdx].isPremium = true;
                          appUsers[uIdx].currentPlan = 'Premium Member';
                          saveUsers(id, true);
                      }

                      // Update directly in Supabase
                      if (window.getSupabase && window.getSupabase()) {
                          const userDocRef = window.supabase.collection('bexo_users').doc(String(id));
                          userDocRef.get().then(doc => {
                              if (doc.exists) {
                                  const userData = doc.data();
                                  userData.isPremium = true;
                                  userData.currentPlan = 'Premium Member';
                                  userDocRef.set(sanitizeForSupabase(userData))
                                      .then(() => alert(`Profile ${id} activated successfully in Supabase!`))
                                      .catch(err => {
                                          console.error(err);
                                          alert(`Error: Could not update Supabase for profile ${id}`);
                                      });
                              } else {
                                  alert(`Profile ${id} not found in database.`);
                              }
                          }).catch(err => {
                              console.error(err);
                              alert(`Error finding user profile ${id}`);
                          });
                      } else {
                          alert(`Profile ${id} status updated locally.`);
                      }
                  }
                  updateAdminStats();
              }

