              function extractYouTubeId(urlOrId) {
                  if (!urlOrId) return '';
                  let str = urlOrId;
                  const iframeMatch = str.match(/src="([^"]+)"/);
                  if (iframeMatch) {
                      str = iframeMatch[1];
                  }
                  const regExp = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?|shorts)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/i;
                  const match = str.match(regExp);
                  if (match && match[1].length === 11) {
                      return match[1];
                  }
                  if (str.trim().length === 11) {
                      return str.trim();
                  }
                  return str.trim();
              }

              window.handleVideoPreview = function(val) {
                  const container = document.getElementById('videoPreviewContainer');
                  const iframe = document.getElementById('videoPreviewIframe');
                  const loading = document.getElementById('videoLoadingState');
                  const openBtn = document.getElementById('openYoutubeBtn');
                  
                  if (!val || val.trim() === '') {
                      container.classList.add('hidden');
                      iframe.src = '';
                      if (openBtn) openBtn.classList.add('hidden');
                      return;
                  }
                  
                  const videoId = extractYouTubeId(val);
                  
                  if (videoId && videoId.length === 11) {
                      container.classList.remove('hidden');
                      loading.classList.remove('hidden');
                      
                      if (openBtn) {
                          openBtn.href = 'https://www.youtube.com/watch?v=' + videoId;
                          openBtn.classList.remove('hidden');
                      }
                      
                      // Simulate short loading to show processing
                      setTimeout(() => {
                          iframe.src = 'https://www.youtube.com/embed/' + videoId;
                          loading.classList.add('hidden');
                      }, 400);
                  } else {
                      container.classList.add('hidden');
                      iframe.src = '';
                      if (openBtn) openBtn.classList.add('hidden');
                  }
              };

              function createPostFromAdmin(pId = null) {
                  const title = document.getElementById('apTitle').value.trim();
                  const cat = document.getElementById('apCategory').value;
                  const sub = document.getElementById('apSubCategory').value;
                  const price = document.getElementById('apPrice').value.trim();
                  const costPrice = document.getElementById('apCost').value.trim();
                  const suggestedMaxPrice = document.getElementById('apMaxPrice').value.trim();
                  const stockCount = parseInt(document.getElementById('apStockCount').value) || 0;
                  const unitType = document.getElementById('apUnit').value;
                  const discountAmount = document.getElementById('apDiscount').value.trim();
                  const remarks = document.getElementById('apRemarks').value.trim();
                  const rawSku = document.getElementById('apSku').value.trim();
                  const sku = rawSku || `SKU-${Date.now().toString().slice(-6)}`;
                  
                  // Check for duplicate SKU
                  const duplicatePost = (typeof appPosts !== 'undefined' ? appPosts : []).find(item => {
                      if (pId && String(pId) !== 'null' && String(pId) !== '' && String(item.id) === String(pId)) return false;
                      return item.sku && String(item.sku).trim().toLowerCase() === sku.toLowerCase();
                  });
                  if (duplicatePost) {
                      showToast(`এই প্রোডাক্ট কোড/SKU (${sku}) টি ইতোমধ্যে অন্য একটি প্রোডাক্টে ("${duplicatePost.title}") ব্যবহৃত হয়েছে!`, 'error');
                      if (typeof showSuccessOverlay === 'function') {
                          showSuccessOverlay("ডুপ্লিকেট প্রোডাক্ট কোড!", `SKU: ${sku} টি ইতোমধ্যে ব্যবহৃত হয়েছে`, "fas fa-exclamation-triangle", "text-red-500", "bg-red-50");
                      }
                      const inputEl = document.getElementById('apSku');
                      if (inputEl) {
                          inputEl.focus();
                          inputEl.classList.add('border-red-500', 'bg-red-50');
                      }
                      return;
                  }
                  const details = document.getElementById('apDetails').value.trim();
                  const imagesText = document.getElementById('apImages').value.trim();
                  const apStockOutCheck = document.getElementById('apStockOut') ? document.getElementById('apStockOut').checked : false;
                  const isStockOut = stockCount <= 0;
                  const autoPost = document.getElementById('apAutoPost').checked;
                  const rating = parseInt(document.getElementById('apRating') ? document.getElementById('apRating').value : 5);

                  // Collect Variants
                  const variants = [];
                  document.querySelectorAll('#adminVariantContainer > div').forEach(group => {
                      const name = group.querySelector('.vg-name').value.trim();
                      const isMandatory = group.querySelector('.vg-mandatory').checked;
                      const options = Array.from(group.querySelectorAll('.vg-option-val')).map(inp => inp.value.trim()).filter(v => v !== '');
                      if (name && options.length > 0) {
                          variants.push({ name, isMandatory, options });
                      }
                  });

                  if (!title || !cat || !sub || !price) {
                      showToast("অনুগ্রহ করে সব তথ্য প্রদান করুন!", 'error');
                      return;
                  }

                  // Image handling
                  let finalImages = imagesText.split(/[\s,]+/).map(l => l.trim()).filter(l => l !== '');
                  
                  // Get the main image
                  let mainImage = '';
                  if (typeof adminUploadedImages !== 'undefined' && adminUploadedImages.length > 0) {
                      mainImage = adminUploadedImages[0];
                  } else {
                      // Grab from preview if it exists
                      const previewImg = document.querySelector('#imagePreview img');
                      if (previewImg && previewImg.src && !previewImg.src.includes(window.location.host) && previewImg.src !== '') {
                          mainImage = previewImg.src;
                      } else if (pId) {
                          const pObj = appPosts.find(item => String(item.id) === String(pId));
                          if (pObj && pObj.images && pObj.images.length > 0) {
                              mainImage = pObj.images[0];
                          }
                      }
                  }

                  if (mainImage) {
                      finalImages = [mainImage, ...finalImages];
                  }

                  if (finalImages.length === 0) {
                      finalImages = [`https://picsum.photos/seed/${Date.now()}/800/600`];
                  }

                  const isBulkUpload = !pId && document.getElementById('apBulkUpload') && document.getElementById('apBulkUpload').checked;
                  
                  let newPosts = [];
                  
                  if (isBulkUpload && finalImages.length > 1) {
                      newPosts = finalImages.map((img, i) => {
                          return {
                              id: Date.now() + i,
                              author: 'বেক্সো অফিসিয়াল',
                              time: 'এইমাত্র',
                              category: cat,
                              subCategory: sub,
                              price: price,
                              costPrice: costPrice,
                              maxSellingPrice: suggestedMaxPrice,
                              stockCount: stockCount,
                              stock: stockCount,
                              stockStatus: isStockOut ? 'out_of_stock' : 'in_stock',
                              unitType: unitType,
                              variants: variants,
                              availableSizes: variants.find(v => v.name.toLowerCase() === 'size')?.options || [],
                              discountAmount: discountAmount,
                              remarks: remarks,
                              isVerified: true,
                              rating: rating,
                              title: title,
                              desc: "",
                              details: details,
                              images: [img],
                              imageCount: 1,
                              videoUrl: document.getElementById('apVideoUrl') ? extractYouTubeId(document.getElementById('apVideoUrl').value.trim()) : '',
                              isStockOut: isStockOut,
                              sku: sku + (i > 0 ? '-' + i : ''),
                              isPublished: autoPost
                          };
                      });
                  } else {
                      newPosts = [{
                          id: pId || Date.now(),
                          author: 'বেক্সো অফিসিয়াল',
                          time: pId ? (appPosts.find(p => String(p.id) === String(pId))?.time || 'এইমাত্র') : 'এইমাত্র',
                          category: cat,
                          subCategory: sub,
                          price: price,
                          costPrice: costPrice,
                          maxSellingPrice: suggestedMaxPrice,
                          stockCount: stockCount,
                          stock: stockCount,
                          stockStatus: isStockOut ? 'out_of_stock' : 'in_stock',
                          unitType: unitType,
                          variants: variants,
                          availableSizes: variants.find(v => v.name.toLowerCase() === 'size')?.options || [],
                          discountAmount: discountAmount,
                          remarks: remarks,
                          isVerified: true,
                          rating: 5,
                          title: title,
                          desc: "",
                          details: details,
                          images: finalImages,
                          imageCount: finalImages.length,
                          videoUrl: document.getElementById('apVideoUrl') ? extractYouTubeId(document.getElementById('apVideoUrl').value.trim()) : '',
                          isStockOut: isStockOut,
                          sku: sku,
                          isPublished: autoPost
                      }];
                  }

                  if (pId) {
                      const idx = appPosts.findIndex(p => String(p.id) === String(pId));
                      if (idx > -1) appPosts[idx] = newPosts[0];
                  } else {
                      appPosts.unshift(...newPosts);
                  }
                  savePosts();

                  if (window.getSupabase && window.getSupabase()) {
                      newPosts.forEach(postData => {
                          window.supabase.collection('bexo_posts').doc(String(postData.id)).set(sanitizeForSupabase(postData))
                              .catch(err => console.warn("Supabase save post error:", err));
                      });
                  }

                  // Success feedback
                  if (newPosts.length > 1) {
                      showToast(newPosts.length + " টি পণ্য সফলভাবে সংরক্ষিত হয়েছে!");
                  } else {
                      showToast(pId ? "পণ্যটি সফলভাবে আপডেটেড হয়েছে!" : "পণ্যটি সফলভাবে সংরক্ষিত হয়েছে!");
                  }

                  // Refresh view
                  renderAdminPostList();

                  // Cleanup
                  if (typeof adminUploadedImages !== 'undefined') adminUploadedImages = [];
              }

              function updateAdminSubOptions(catName) {
                  const subSelect = document.getElementById('apSubCategory');
                  if(!subSelect) return;
                  const cat = appCategories.find(c => c.name === catName);
                  if(cat) {
                      subSelect.innerHTML = `<option value="">পছন্দ করুন</option>` + cat.subCategories.sort((a,b) => a.order - b.order).map(s => `<option value="${s.name}">${s.name}</option>`).join('');
                  } else {
                      subSelect.innerHTML = '<option value="">সিলেক্ট করুন</option>';
                  }
              }
              function deletePost(id) {
                  if(!confirm("আপনি কি নিশ্চিতভাবে এই পোস্টটি ডিলিট করতে চান?")) return;
                  appPosts = appPosts.filter(p => String(p.id) !== String(id));
                  savePosts();
                  if (window.getSupabase && window.getSupabase()) {
                      window.supabase.collection('bexo_posts').doc(String(id)).delete()
                          .catch(err => console.warn("Supabase delete product error:", err));
                  }
                  renderAdminPostList();
              }

              function toggleStockStatus(id) {
                  const p = appPosts.find(item => String(item.id) === String(id));
                  if(p) {
                      const isCurrentlyOut = window.isProductOutOfStock(p);
                      if (isCurrentlyOut) {
                          p.isStockOut = false;
                          p.stockStatus = 'in_stock';
                          p.stockCount = (p.stockCount && p.stockCount > 0) ? p.stockCount : 10;
                          p.stock = p.stockCount;
                      } else {
                          p.isStockOut = true;
                          p.stockStatus = 'out_of_stock';
                          p.stockCount = 0;
                          p.stock = 0;
                      }
                      savePosts();
                      if (window.getSupabase && window.getSupabase()) {
                          window.supabase.collection('bexo_posts').doc(String(id)).set(sanitizeForSupabase(p))
                              .catch(err => console.warn("Supabase update product error:", err));
                      }
                      renderAdminPostList();
                  }
              }

              function togglePublishStatus(id) {
                  const p = appPosts.find(item => String(item.id) === String(id));
                  if(p) {
                      p.isPublished = (p.isPublished === false) ? true : false;
                      savePosts();
                      if (window.getSupabase && window.getSupabase()) {
                          window.supabase.collection('bexo_posts').doc(String(id)).set(sanitizeForSupabase(p))
                              .catch(err => console.warn("Supabase update product error:", err));
                      }
                      renderAdminPostList();
                  }
              }

