                                              const total = Number(o.grandTotal || o.total) || 0;
                                              const advance = Number(o.advancePaid) || 0;
                                              const due = total - advance; const user = appUsers.find(u => (o.profileId && u.profileId === o.profileId) || (o.resellerPhone && u.phone === o.resellerPhone));

