                      const qty = o.items ? o.items.reduce((sum, item) => sum + (item.qty || 1), 0) : 1;
                      totalSale += Number(o.totalSellingPrice || 0);
                      totalProfit += Number(o.totalProfit || 0);
                      totalBase += Number(o.totalBasePrice || 0);
