              function verifySupportOrder() {
                  const val = document.getElementById('supportOrderId').value;
                  const box = document.getElementById('supportOrderDetails');
                  if(!val) { box.classList.add('hidden'); return; }
                  const o = appOrders.find(item => item.orderNo === val || String(item.id) === val);
                  if(o) {
                      document.getElementById('sup-cust-name').innerText = 'গ্রাহকের নাম: ' + o.customerName;
                      document.getElementById('sup-cust-phone').innerText = 'মোবাইল নম্বর: ' + o.customerPhone;
                      box.classList.remove('hidden');
                  } else {
                      document.getElementById('sup-cust-name').innerText = 'অর্ডার খুঁজে পাওয়া যায়নি!';
                      document.getElementById('sup-cust-phone').innerText = 'অবাক ভেরিফিকেশন বাতিল';
                      box.classList.remove('hidden');
                  }
              }

              function submitSupportTicket() {
                  const isOrder = (window.newUserTicketType || 'order') === 'order';
                  let orderId = 'General';

                  if (isOrder) {
                      const orderInput = document.getElementById('supportOrderId');
                      orderId = orderInput ? orderInput.value.trim() : '';
                      if (!orderId) {
                          alert('অনুগ্রহ করে অর্ডার আইডি সঠিক ভাবে প্রদান করুন।');
                          return;
                      }
                  }

                  const message = document.getElementById('supportMessage').value.trim();

                  if (!message) {
                      alert('অনুগ্রহ করে সমস্যার বিবরণ বা বার্তাটি লিখুন।');
                      return;
                  }

                  const newTicket = {
                      id: Date.now(),
                      profileId: userProfile.profileId,
                      date: new Date().toISOString().split('T')[0],
                      orderId: orderId,
                      status: 'Pending',
                      customerName: userProfile.fullName || 'User ' + userProfile.phone,
                      customerPhone: userProfile.phone,
                      messages: [
                          { sender: 'User', text: message, time: new Date().toLocaleString() }
                      ]
                  };

                  appSupportTickets.unshift(newTicket);
                  saveSupportTickets();

                  window.activeUserSupportTicketId = newTicket.id;
                  renderSupportTicket();
              }

