               // 8. Settle: Confirm Delivery handler
               function settleConfirmDelivery(orderId) {
                   try {
                       updateOrderStatus(orderId, 'Delivery Completed', 'Admin');
                       // Re-load the details screen after updating
                       const idx = appOrders.findIndex(o => String(o.id) === String(orderId));
                       if (idx > -1) {
                           showToast("অর্ডার ডেলিভারি নিশ্চিত করা হয়েছে।", "success");
                           renderLoadedSettlementDetailsCard(appOrders[idx]);
                       }
                   } catch (e) {
                       console.error("Delivery status shift error:", e);
                       showToast("ডেলিভারি স্থিতি পরিবর্তন ব্যর্থ হয়েছে।", "error");
                   }
               }

               // 9. Interactive update change listeners
               function updateSettleCalculation(orderId) {
                   const order = (appOrders || []).find(o => String(o.id) === String(orderId));
                   if (!order) return;

                   const sellingPrice = Number(order.totalSellingPrice || order.total || 0);
                   const basePrice = Number(order.totalBasePrice || 0);

                   const deliveryInput = document.getElementById('settleDeliveryChargeInput');
                   const deductionsInput = document.getElementById('settleDeductionsInput');
                   const profitDisplay = document.getElementById('settleProfitDisplay');

                   if (!deliveryInput || !deductionsInput || !profitDisplay) return;

                   const courierCharge = Number(deliveryInput.value) || 0;
                   const deductions = Number(deductionsInput.value) || 0;

                   // Formula: Net Profit = Selling Price - Base - Courier - Deductions
                   const computedProfit = Math.max(0, sellingPrice - basePrice - courierCharge - deductions);

                   // Realtime Update Display with green colors
                   profitDisplay.innerText = computedProfit.toLocaleString();

                   // Guard button state from negative profits if desired (we just computed)
                   const actionBtn = document.getElementById('settlePaymentActionButton');
                   if (actionBtn) {
                       if (computedProfit <= 0) {
                           actionBtn.classList.add('bg-slate-300', 'text-slate-500');
                           actionBtn.classList.remove('bg-orange-600', 'hover:bg-emerald-600');
                       } else {
                           actionBtn.classList.remove('bg-slate-300', 'text-slate-500');
                           actionBtn.classList.add('bg-orange-600', 'hover:bg-emerald-600');
                       }
                   }
               }

               // 10. Settle Payment implementation with ACID Transaction Integrity
               async function executeSettlePayment(orderId) {
                   const orderIdx = appOrders.findIndex(o => String(o.id) === String(orderId));
                   if (orderIdx === -1) {
                       showToast("অর্ডার পাওয়া যায়নি!", "error");
                       return;
                   }

                   const order = appOrders[orderIdx];
                   if (order.isProfitDistributed) {
                       showToast("এই অর্ডারের প্রফিট ইতিপূর্বে সেটেল করা হয়েছে!", "error");
                       return;
                   }

                   // Get interactive parameters values
                   const deliveryInput = document.getElementById('settleDeliveryChargeInput');
                   const deductionsInput = document.getElementById('settleDeductionsInput');

                   const courierCharge = deliveryInput ? Number(deliveryInput.value) : Number(order.shipping ? order.shipping.courierCharge : 0);
                   const deductions = deductionsInput ? Number(deductionsInput.value) : 0;

                   const sellingPrice = Number(order.totalSellingPrice || order.total || 0);
                   const basePrice = Number(order.totalBasePrice || 0);

                   // Compute profit
                   const computedProfit = Math.max(0, sellingPrice - basePrice - courierCharge - deductions);
                   const resellerProfileId = order.profileId;

                   if (!resellerProfileId) {
                       showToast("ত্রুটি: রেসেলারের প্রোফাইল আইডি পাওয়া যায়নি!", "error");
                       return;
                   }

                   // Confirm Action dialog alert style (Using simple premium UI instead of blocky alert)
                   if (!confirm(`আপনি কি এই অর্ডারের জন্য ৳${computedProfit} প্রফিট নিষ্পত্তি নিশ্চিত করতে চান? এটি রেসেলার ওয়ালেটে সরাসরি যুক্ত করা হবে।`)) {
                       return;
                   }

                   // Update Status: Setup Loader
                   const actionBtn = document.getElementById('settlePaymentActionButton');
                   if (actionBtn) {
                       actionBtn.disabled = true;
                       actionBtn.innerHTML = `<i class="fas fa-spinner animate-spin"></i> প্রসেস হচ্ছে...`;
                   }

                   // Build immutability payloads
                   const settlementTxnId = 'SETTLE-TXN-' + Date.now();
                   const timestamp = new Date().toLocaleString('en-GB');

                   const auditTxnEntry = {
                       id: settlementTxnId,
                       date: timestamp,
                       timestamp: Date.now(),
                       profileId: resellerProfileId,
                       userId: order.resellerPhone || resellerProfileId,
                       orderNo: order.orderNo || order.id,
                       secretToken: order.secretToken || 'N/A',
                       sellingPrice: sellingPrice,
                       basePrice: basePrice,
                       courierCharge: courierCharge,
                       otherDeductions: deductions,
                       netProfit: computedProfit,
                       adminId: 'admin@bexo.com',
                       adminName: 'Super Admin',
                       clientIP: window.adminClientIP || '103.118.42.10',
                       type: 'Reseller Settlement',
                       status: 'Success',
                       details: `Settlement for order #${order.orderNo || order.id} (Deductions: ৳${deductions})`
                   };

                   const userTxEntry = {
                       id: 'TX-PROFIT-' + Date.now(),
                       type: 'Order Profit',
                       details: `Profit from order #${order.orderNo || order.id} (Settle Audit: Net ৳${computedProfit})`,
                       amount: computedProfit,
                       time: timestamp
                   };

                   // Execute ACID Transaction process
                   try {
                       if (window.getSupabase && window.getSupabase()) {
                           // Use relational atomicity transaction across Supabase if online!
                           const userDocRef = window.supabase.collection('bexo_users').doc(String(resellerProfileId));
                           const orderDocRef = window.supabase.collection('bexo_orders').doc(String(order.id));
                           const txnDocRef = window.supabase.collection('bexo_transactions').doc(String(settlementTxnId));

                           await window.supabase.runTransaction(async (transaction) => {
                               // Read active order from inside transactional bounds
                               const orderDoc = await transaction.get(orderDocRef);
                               const orderData = orderDoc.data() || {};
                               if (orderData.isProfitDistributed) {
                                   throw new Error("This order has already been settled in a different session!");
                               }

                               // Perform updates atomically inside transaction
                               // Note: User balance is NO LONGER updated automatically here. 
                               // Funds are only added via manual Profile Payment approval workflow.

                               transaction.update(orderDocRef, {
                                   isProfitDistributed: true,
                                   settlementDeductions: deductions,
                                   settledProfitValue: computedProfit,
                                   status: 'Delivery Completed'
                               });

                               transaction.set(txnDocRef, sanitizeForSupabase(auditTxnEntry));
                           });
                       }

                       // Synchronize status locally
                       // NOTE: User balance update logic removed per strict manual-only workflow rules.

                       // Mark local order object
                       order.isProfitDistributed = true;
                       order.settlementDeductions = deductions;
                       order.settledProfitValue = computedProfit;
                       order.status = 'Delivery Completed';
                       order.history = order.history || [];
                       order.history.push({
                           time: timestamp,
                           actor: 'Super Admin',
                           message: `লভ্যাংশ নিষ্পত্তি করা হয়েছে: ৳${computedProfit} (কর্তন: ৳${deductions})`
                       });
                       saveOrders();

                       // Log globally
                       appTransactions.unshift(auditTxnEntry);
                       saveTransactions();

                       // Render Overlay Success Message
                       if (typeof showSuccessOverlay === 'function') {
                           showSuccessOverlay(
                               "নিষ্পত্তি সম্পূর্ণ!",
                               `৳${computedProfit} নেট প্রফিট সফলভাবে রেসেলার ওয়ালেটে যুক্ত করা হয়েছে। (কর্তন: ৳${deductions})`,
                               "fas fa-check-circle",
                               "text-emerald-500",
                               "bg-slate-950 font-sans"
                           );
                       } else {
                           showToast("সেটেলমেন্ট সফলভাবে সম্পন্ন হয়েছে!", "success");
                       }

                       // Refresh Views
                       renderResellerSettlementModule();

                   } catch (err) {
                       console.error("ACID Settlement Transaction Failed:", err);
                       showToast("হিসাব নিষ্পত্তি সম্পন্ন করা সম্ভব হয়নি: " + err.message, "error");
                       
                       // Reset button loading state
                       if (actionBtn) {
                           actionBtn.disabled = false;
                           actionBtn.innerHTML = `<i class="fas fa-hand-holding-usd"></i> পেমেন্ট সেটেলমেন্ট নিশ্চিত করুন`;
                       }
                   }
               }

               // 11. Render Immutable Audit logs table historical details
               function renderSettlementAuditLogsTable() {
                   const tbody = document.getElementById('settlementLogsTbody');
                   const counter = document.getElementById('settleLogCount');
                   if (!tbody) return;

                   // Filter settlements from appTransactions history log
                   const settlements = appTransactions.filter(t => t.type === 'Reseller Settlement');
                   
                   if (counter) counter.innerText = settlements.length;

                   if (settlements.length === 0) {
                       tbody.innerHTML = `
                           <tr>
                               <td colspan="6" class="p-5 sm:p-12 text-center text-slate-300 font-bold whitespace-nowrap">বর্তমানে কোন নিষ্পত্তির রেকর্ড পাওয়া যায়নি।</td>
                           </tr>
                       `;
                       return;
                   }

                   tbody.innerHTML = settlements.map(t => {
                       return `
                           <tr class="hover:bg-slate-50 transition-all">
                               <td class="px-4 sm:px-8 py-5">
                                   <p class="font-black text-slate-700 tracking-wider text-left">${t.id}</p>
                                   <p class="text-[10px] text-slate-400 font-semibold mt-0.5 text-left">${t.date}</p>
                               </td>
                               <td class="px-4 sm:px-8 py-5">
                                   <p class="font-black text-slate-800 text-left">অর্ডার #${t.orderNo}</p>
                                   <div class="text-left">
                                       <span class="inline-flex items-center gap-1 bg-orange-50 text-orange-600 px-2 py-0.5 rounded text-[9px] font-black mt-1 uppercase border border-orange-100 italic">
                                           <i class="fas fa-barcode"></i> ${t.secretToken || 'N/A'}
                                       </span>
                                   </div>
                               </td>
                               <td class="px-4 sm:px-8 py-5">
                                   <p class="font-bold text-slate-700 flex items-center gap-1 text-left">
                                       <i class="fas fa-user-circle text-slate-400"></i> ${t.userId || 'System'}
                                   </p>
                               </td>
                               <td class="px-4 sm:px-8 py-5 text-slate-500 font-semibold text-left">
                                   <div class="space-y-0.5 text-[10px] text-left">
                                       <p>বিক্রয়: ৳${t.sellingPrice}</p>
                                       <p>কেনার: ৳${t.basePrice}</p>
                                       <p>ডেলিভারি: ৳${t.courierCharge}</p>
                                       <p class="text-rose-600 font-black">কর্তন: ৳${t.otherDeductions || 0}</p>
                                   </div>
                               </td>
                               <td class="px-4 sm:px-8 py-5 font-black text-emerald-600 font-mono text-sm text-left">
                                   ৳ ${(Number(t.netProfit) || 0).toLocaleString()}
                               </td>
                               <td class="px-4 sm:px-8 py-5 text-right font-semibold text-slate-400">
                                   <p class="text-[10px] text-slate-700 font-black flex items-center justify-end gap-1">
                                       <i class="fas fa-user-shield text-indigo-500"></i> ${t.adminName || 'Admin'}
                                   </p>
                                   <p class="text-[9px] font-mono mt-0.5">${t.clientIP || '127.0.0.1'}</p>
                               </td>
                           </tr>
                       `;
                    }).join('');
                }

// --- LANDING PAGE LOGIC ---
window.showAuth = function(isLogin) {
    var landing = document.getElementById('landingSection');
    const auth = document.getElementById('authSection');
    
    if (landing) landing.classList.add('hidden');
    if (auth) {
        auth.classList.remove('hidden');
        auth.classList.add('flex');
    }
    
    // Call the existing toggleAuth function which switches between login and register forms
    if (typeof toggleAuth === 'function') {
        toggleAuth(isLogin);
    }
};

let selectedLandingCategory = null;

function selectLandingCategory(category) {
    selectedLandingCategory = category;
    loadLandingProducts();
}

async function loadLandingProducts() {
    const container = document.getElementById('landingProductsContainer');
    if (!container) return;
    
    const catContainer = document.getElementById('landingCategoriesContainer');
    if (catContainer) {
        catContainer.innerHTML = '';
        catContainer.style.display = 'none';
    }
    
    try {
        let products = [];
        
        // Attempt to fetch from window.supabase first if it's initialized
        if (window.supabase && typeof window.supabase.collection === 'function') {
            try {
                const snapshot = await window.supabase.collection('bexo_posts').get();
                if (snapshot && typeof snapshot.forEach === 'function') {
                    snapshot.forEach(doc => {
                        const data = typeof doc.data === 'function' ? doc.data() : doc;
                        if (data) {
                            products.push(data);
                        }
                    });
                } else if (snapshot && Array.isArray(snapshot.data)) {
                    products = [...snapshot.data];
                } else if (Array.isArray(snapshot)) {
                    products = [...snapshot];
                }
            } catch (err) {
                console.error("Failed to fetch landing products from supabase directly:", err);
            }
        }
        
        // Fallback to local appPosts if database fetch returned nothing (or database is not ready/failed)
        if (products.length === 0 && typeof appPosts !== 'undefined' && Array.isArray(appPosts) && appPosts.length > 0) {
            products = [...appPosts];
        }
        
        // Filter published and in-stock products
        let activeProducts = products.filter(p => {
            const isPublished = p.isPublished !== false;
            const isStockOut = p.isStockOut === true || (p.stockCount !== undefined && p.stockCount <= 0);
            return isPublished && !isStockOut;
        });
        
        // Extract unique, non-empty category names from active products
        const catSet = new Set();
        activeProducts.forEach(p => {
            if (p.category && typeof p.category === 'string' && p.category.trim()) {
                catSet.add(p.category.trim());
            }
        });
        const uniqueCategories = Array.from(catSet).sort();
        
        // If no category is selected, render the Visual Category Grid
        if (!selectedLandingCategory) {
            if (uniqueCategories.length === 0) {
                container.innerHTML = `
                    <div class="col-span-full py-12 text-slate-500 font-bold bg-white/60 rounded-2xl border border-dashed border-slate-200 flex flex-col items-center justify-center gap-3">
                        <i class="fas fa-th-large text-slate-400 text-3xl"></i>
                        <span>কোন ক্যাটাগরি পাওয়া যায়নি।</span>
                    </div>
                `;
                return;
            }
            
            // Build category thumbnail mapping from first active product of each category or bexo_categories
            const catImageMap = {};
            activeProducts.forEach(p => {
                if (p.category && typeof p.category === 'string' && p.category.trim()) {
                    const catName = p.category.trim();
                    if (!catImageMap[catName] && p.images && p.images.length > 0) {
                        catImageMap[catName] = p.images[0];
                    }
                }
            });
            
            const findCatImg = (catName) => {
                if (catImageMap[catName]) return catImageMap[catName];
                if (typeof appCategories !== 'undefined' && Array.isArray(appCategories)) {
                    const found = appCategories.find(c => c && c.name && c.name.trim() === catName);
                    if (found && found.image) return found.image;
                }
                return 'https://via.placeholder.com/150';
            };
            
            let categoriesHtml = uniqueCategories.map(cat => {
                const imageUrl = findCatImg(cat);
                const count = activeProducts.filter(p => p.category && p.category.trim() === cat).length;
                return `
                  <div onclick="selectLandingCategory('${cat}')" class="bg-white rounded flex flex-col items-center p-1.5 shadow-sm cursor-pointer relative group border border-transparent hover:shadow-md transition-all">
                    <div class="absolute top-1 right-1.5 text-[10px] font-bold text-[#6a1b9a] z-10">${typeof toBengaliNumber === 'function' ? toBengaliNumber(count) : count}</div>
                    <div class="w-full aspect-square flex items-center justify-center p-2 mb-1">
                      <img src="${imageUrl}" alt="${cat}" referrerpolicy="no-referrer" loading="lazy" class="w-full h-full object-contain mix-blend-multiply group-hover:scale-110 transition-transform duration-500" onerror="this.src='https://via.placeholder.com/150'">
                    </div>
                    <div class="text-center w-full pb-1">
                      <p class="text-[11px] sm:text-[12px] font-semibold text-[#6a1b9a] truncate">${cat}</p>
                    </div>
                  </div>
                `;
            }).join('');
            
            container.innerHTML = categoriesHtml;
            return;
        }
        
        // Filter products belonging to selected category
        let categoryProducts = activeProducts.filter(p => p.category && p.category.trim() === selectedLandingCategory);
        
        // Sort by ID descending (newest first)
        categoryProducts.sort((a, b) => Number(b.id) - Number(a.id));
        
        // Slice to max 24 products
        categoryProducts = categoryProducts.slice(0, 24);
        
        let htmlStr = `
            <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-6 w-full col-span-full text-left">
              <button onclick="selectLandingCategory(null)" class="flex items-center justify-center gap-2 px-4 py-2 bg-white text-slate-700 border border-slate-200 rounded-xl text-xs font-bold shadow-sm hover:text-orange-600 hover:bg-orange-50 hover:border-orange-200 transition-all cursor-pointer w-fit">
                <i class="fas fa-arrow-left"></i> ব্যাক (সব ক্যাটাগরি)
              </button>
              <div class="flex items-center gap-2 bg-orange-50 border border-orange-100 px-4 py-2 rounded-xl w-fit">
                <span class="text-xs font-bold text-slate-500">নির্বাচিত ক্যাটাগরি:</span>
                <span class="text-xs font-black text-orange-600">${selectedLandingCategory}</span>
              </div>
            </div>
        `;
        
        if (categoryProducts.length === 0) {
            htmlStr += '<div class="col-span-full py-12 text-slate-400 text-center font-bold bg-white/60 rounded-2xl border border-dashed border-slate-200">এই ক্যাটাগরিতে কোন প্রোডাক্ট পাওয়া যায়নি।</div>';
            container.innerHTML = htmlStr;
            return;
        }
        
        categoryProducts.forEach(p => {
            const mainImg = (p.images && p.images.length > 0) ? p.images[0] : 'https://via.placeholder.com/150';
            const title = p.title || 'Unknown Product';
            const price = p.price || 0;
            
            htmlStr += `
              <div class="bg-white rounded flex flex-col items-center p-1.5 shadow-sm cursor-pointer relative group border border-transparent hover:shadow-md transition-all" onclick="showAuth(false)">
                  <div class="absolute top-1 right-1.5 text-[10px] sm:text-[12px] font-bold text-[#6a1b9a] z-10">${typeof toBengaliNumber === 'function' ? toBengaliNumber(price) : price}</div>
                  <div class="w-full aspect-square flex items-center justify-center p-2 mb-1 relative overflow-hidden">
                      <img src="${mainImg}" alt="${title}" referrerpolicy="no-referrer" loading="lazy" class="w-full h-full object-contain mix-blend-multiply group-hover:scale-110 transition-transform duration-500" onerror="this.src='https://via.placeholder.com/150'">
                  </div>
                  <div class="text-center w-full pb-1">
                      <p class="text-[11px] sm:text-[12px] font-semibold text-[#6a1b9a] truncate">${title}</p>
                  </div>
              </div>
            `;
        });
        
        container.innerHTML = htmlStr;
        
    } catch (error) {
        console.error("Error loading landing products:", error);
        container.innerHTML = '<div class="col-span-full py-5 sm:py-10 text-rose-400 text-center text-sm"><i class="fas fa-exclamation-triangle mb-2 text-2xl"></i><br/>প্রোডাক্ট লোড করতে সমস্যা হয়েছে।</div>';
    }
}

document.addEventListener('DOMContentLoaded', () => {
    // Render immediately using local posts cache if available
    loadLandingProducts();
    
    if (window.supabase !== null && typeof window.supabase !== 'undefined') {
        loadLandingProducts();
    } else {
        const interval = setInterval(() => {
            if (window.supabase !== null && typeof window.supabase !== 'undefined') {
                clearInterval(interval);
                loadLandingProducts();
            }
        }, 500);
        setTimeout(() => clearInterval(interval), 10000);
    }
});
